function New-GmsaAccount {
<#
.SYNOPSIS
Creates a group Managed Service Account and the group of servers allowed to use it, creating the KDS root key first if the domain has none.
.DESCRIPTION
Steps: check Get-KdsRootKey (add one with -EffectiveImmediately if missing - in a multi-DC domain wait up to 10 hours
for replication, or use a backdated key in a lab only); create the host group; add the servers' computer accounts;
create the gMSA allowed to retrieve its password by that group.
.PARAMETER Name
gMSA name without the $ (15 characters max).
.PARAMETER DnsHostName
DNS name for the account, e.g. svc-backup.contoso.com.
.PARAMETER HostGroup
Group of servers allowed to use it. Created if missing.
.PARAMETER Server
Computer names of the servers that will use it, one per line.
.PARAMETER Path
OU for the host group. Empty = the default Users container.
.EXAMPLE
New-GmsaAccount -Name svc-backup -DnsHostName svc-backup.contoso.com -HostGroup gMSA-Backup-Hosts -Server APP01
.NOTES
Each server must reboot (or run klist -li 0x3e7 purge) before it sees its new group membership. Then run Install-GmsaOnServer on it.
#>
    [CmdletBinding(SupportsShouldProcess)]
    param(
        [Parameter(Mandatory)] [ValidateLength(1, 15)] [string]$Name,
        [Parameter(Mandatory)] [string]$DnsHostName,
        [Parameter(Mandatory)] [string]$HostGroup,
        [string[]]$Server = @(),
        [string]$Path
    )
    if (-not @(Get-KdsRootKey).Count) {
        if ($PSCmdlet.ShouldProcess('domain', 'Add-KdsRootKey -EffectiveImmediately')) {
            Add-KdsRootKey -EffectiveImmediately | Out-Null
            Write-Warning 'KDS root key created. With more than one DC, wait for replication (up to 10 hours) before the gMSA works.'
        }
    }
    $g = Get-ADGroup -Filter "Name -eq '$($HostGroup -replace "'", "''")'" -ErrorAction SilentlyContinue
    if (-not $g -and $PSCmdlet.ShouldProcess($HostGroup, 'New-ADGroup (Global Security)')) {
        $gp = @{ Name = $HostGroup; GroupScope = 'Global'; GroupCategory = 'Security'; Description = "Servers allowed to use gMSA $Name" }
        if ($Path) { $gp.Path = $Path }
        New-ADGroup @gp
        $g = Get-ADGroup -Identity $HostGroup
    }
    foreach ($s in $Server) {
        $c = Get-ADComputer -Identity $s
        if ($g -and $PSCmdlet.ShouldProcess($HostGroup, "Add member $($c.Name)$")) { Add-ADGroupMember -Identity $g -Members $c }
    }
    if (Get-ADServiceAccount -Filter "Name -eq '$Name'" -ErrorAction SilentlyContinue) { Write-Warning "gMSA $Name already exists - not created again." }
    elseif ($PSCmdlet.ShouldProcess($Name, 'New-ADServiceAccount')) {
        New-ADServiceAccount -Name $Name -DNSHostName $DnsHostName -PrincipalsAllowedToRetrieveManagedPassword $HostGroup -Enabled $true
    }
    $a = Get-ADServiceAccount -Filter "Name -eq '$Name'" -Properties PrincipalsAllowedToRetrieveManagedPassword -ErrorAction SilentlyContinue
    [pscustomobject]@{ gMSA = "$Name$"; Exists = [bool]$a; AllowedToRetrieve = $(if ($a) { (@($a.PrincipalsAllowedToRetrieveManagedPassword) | ForEach-Object { ($_ -split ',')[0] -replace '^CN=' }) -join ', ' } else { '' }); HostGroupMembers = $(if ($g) { (@(Get-ADGroupMember -Identity $g) | ForEach-Object { $_.Name }) -join ', ' } else { '' }) }
}

function Install-GmsaOnServer {
<#
.SYNOPSIS
Adds the AD PowerShell feature if needed, refreshes the computer's group membership, installs the gMSA and tests it.
.PARAMETER Name
gMSA name (with or without $).
.EXAMPLE
Install-GmsaOnServer -Name svc-backup
.NOTES
Test-ADServiceAccount = False usually means the server is not yet in the host group, or has not refreshed its Kerberos ticket (reboot).
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)] [string]$Name)
    $Name = $Name.TrimEnd('$')
    if (-not (Get-Module -ListAvailable ActiveDirectory)) {
        if (Get-Command Install-WindowsFeature -ErrorAction SilentlyContinue) {
            if ($PSCmdlet.ShouldProcess($env:COMPUTERNAME, 'Install-WindowsFeature RSAT-AD-PowerShell')) { Install-WindowsFeature RSAT-AD-PowerShell | Out-Null }
        }
        else { throw 'ActiveDirectory module missing. On Windows 10/11: Add-WindowsCapability -Online -Name Rsat.ActiveDirectory.DS-LDS.Tools~~~~0.0.1.0' }
    }
    Import-Module ActiveDirectory
    if ($PSCmdlet.ShouldProcess($env:COMPUTERNAME, 'klist purge (computer tickets)')) { klist -li 0x3e7 purge | Out-Null }
    if ($PSCmdlet.ShouldProcess($Name, 'Install-ADServiceAccount')) { Install-ADServiceAccount -Identity $Name }
    [pscustomobject]@{ Computer = $env:COMPUTERNAME; gMSA = "$Name$"; Test = (Test-ADServiceAccount -Identity $Name); RunAs = "$env:USERDOMAIN\$Name$ (leave the password empty)" }
}

function Get-ADGroupMemberSummary {
<#
.SYNOPSIS
Every group with its AD path, member count, enabled and disabled user counts, and when it last changed.
.PARAMETER SearchBase
Only groups under this OU.
.PARAMETER Server
Domain or DC.
.EXAMPLE
Get-ADGroupMemberSummary -SearchBase 'OU=Groups,DC=contoso,DC=com'
.NOTES
Groups whose members are all disabled are cleanup candidates. Counts are direct members only.
#>
    [CmdletBinding()]
    param([string]$SearchBase, [string]$Server)
    $gp = @{ Filter = '*'; Properties = 'Members', 'whenChanged', 'CanonicalName' }
    if ($SearchBase) { $gp.SearchBase = $SearchBase }
    if ($Server) { $gp.Server = $Server }
    $up = @{ Filter = '*'; Properties = 'Enabled' }
    if ($Server) { $up.Server = $Server }
    $enabled = @{}
    foreach ($u in @(Get-ADUser @up)) { $enabled[$u.DistinguishedName] = [bool]$u.Enabled }
    foreach ($g in @(Get-ADGroup @gp | Sort-Object Name)) {
        $m = @($g.Members)
        $users = @($m | Where-Object { $enabled.ContainsKey($_) })
        $on = @($users | Where-Object { $enabled[$_] }).Count
        [pscustomobject]@{
            Group         = $g.Name
            Path          = ($g.CanonicalName -replace '/[^/]+$', '')
            Members       = $m.Count
            EnabledUsers  = $on
            DisabledUsers = $users.Count - $on
            OtherMembers  = $m.Count - $users.Count
            Scope         = [string]$g.GroupScope
            Changed       = $g.whenChanged
        }
    }
}

function Get-LockedOutUser {
<#
.SYNOPSIS
Accounts that are locked out right now, when they were locked, for how long, and bad-password details.
.PARAMETER Server
Domain or DC to ask. Empty = the PDC emulator (it knows every lockout first).
.PARAMETER SearchBase
Only accounts under this OU.
.EXAMPLE
Get-LockedOutUser
.NOTES
To find the computer causing a lockout, run Get-LockoutSource on the PDC emulator.
#>
    [CmdletBinding()]
    param([string]$Server, [string]$SearchBase)
    if (-not $Server) { $Server = (Get-ADDomain).PDCEmulator }
    $policy = Get-ADDefaultDomainPasswordPolicy -Server $Server
    $p = @{ LockedOut = $true; UsersOnly = $true; Server = $Server }
    if ($SearchBase) { $p.SearchBase = $SearchBase }
    $now = Get-Date
    foreach ($a in @(Search-ADAccount @p)) {
        $u = Get-ADUser -Identity $a.SamAccountName -Server $Server -Properties AccountLockoutTime, BadLogonCount, LastBadPasswordAttempt, DisplayName
        $mins = if ($u.AccountLockoutTime) { [math]::Round(($now - $u.AccountLockoutTime).TotalMinutes) } else { $null }
        $unlockAt = if ($u.AccountLockoutTime -and $policy.LockoutDuration.TotalMinutes -gt 0) { $u.AccountLockoutTime + $policy.LockoutDuration } else { $null }
        [pscustomobject]@{
            User             = $u.SamAccountName
            DisplayName      = $u.DisplayName
            LockedAt         = $u.AccountLockoutTime
            MinutesLocked    = $mins
            AutoUnlockAt     = $(if ($unlockAt) { $unlockAt } else { 'Admin must unlock' })
            BadLogonCount    = $u.BadLogonCount
            LastBadPassword  = $u.LastBadPasswordAttempt
        }
    }
}

function Get-LockoutSource {
<#
.SYNOPSIS
Lockout events (4740) from the Security log, with the computer the bad passwords came from.
.PARAMETER UserName
Only this account. Empty = all lockouts.
.PARAMETER Hours
How far back.
.EXAMPLE
Get-LockoutSource -UserName jsmith -Hours 24
.NOTES
Run it on the PDC emulator ("Run on these computers" with the PDC's name). A phone, a mapped drive or a
service with an old password is usually the source.
#>
    [CmdletBinding()]
    param([string]$UserName, [int]$Hours = 24)
    Get-WinEvent -FilterHashtable @{ LogName = 'Security'; Id = 4740; StartTime = (Get-Date).AddHours(-$Hours) } -ErrorAction SilentlyContinue |
        ForEach-Object {
            $x = [xml]$_.ToXml()
            $d = @{}
            foreach ($n in $x.Event.EventData.Data) { $d[$n.Name] = $n.'#text' }
            if ($UserName -and $d['TargetUserName'] -ne $UserName) { return }
            [pscustomobject]@{ Time = $_.TimeCreated; User = $d['TargetUserName']; CallerComputer = $d['TargetDomainName']; DC = $env:COMPUTERNAME }
        }
}

function Get-DomainUserNet {
<#
.SYNOPSIS
Account details from "net user <name> /domain": active, expiry, password last set/expires, last logon, groups. Works where RSAT is not installed.
.PARAMETER UserName
Account name, one per line.
.EXAMPLE
Get-DomainUserNet -UserName jsmith
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string[]]$UserName)
    foreach ($u in $UserName) {
        $out = @(net user $u /domain 2>&1 | ForEach-Object { [string]$_ })
        if ($LASTEXITCODE -ne 0) { Write-Error "net user $u failed: $(($out | Where-Object { $_ }) -join ' ')"; continue }
        $h = [ordered]@{ User = $u }
        $groups = @()
        $inGroups = $false
        foreach ($l in $out) {
            if ($l -match '^(Local|Global) Group Memberships\s+(.*)$') { $inGroups = $true; $groups += ($Matches[2] -split '\*' | ForEach-Object { $_.Trim() } | Where-Object { $_ }); continue }
            if ($inGroups -and $l -match '^\s+\*') { $groups += ($l -split '\*' | ForEach-Object { $_.Trim() } | Where-Object { $_ }); continue }
            if ($l -match 'command completed') { break }
            $inGroups = $false
            if ($l -match '^(Full Name|Account active|Account expires|Password last set|Password expires|Password changeable|Password required|User may change password|Workstations allowed|Logon hours allowed|Last logon|Logon script)\s{2,}(.*)$') { $h[($Matches[1] -replace '\s', '')] = $Matches[2].Trim() }
        }
        $h['Groups'] = ($groups -join ', ')
        [pscustomobject]$h
    }
}

function Send-PasswordExpiryNotice {
<#
.SYNOPSIS
Finds enabled users whose password expires within N days and emails each one a reminder. Use WhatIf to preview who would get mail.
.PARAMETER SmtpServer
Mail relay.
.PARAMETER From
Sender address.
.PARAMETER DaysBefore
Warn when the password expires within this many days.
.PARAMETER SearchBase
Only users under this OU.
.PARAMETER LogPath
Optional CSV log of who was mailed (a UNC path works).
.PARAMETER TestRecipient
Send every message here instead of to the users.
.EXAMPLE
Send-PasswordExpiryNotice -SmtpServer smtp.contoso.com -From it@contoso.com -DaysBefore 7 -WhatIf
.NOTES
Uses msDS-UserPasswordExpiryTimeComputed, so fine-grained password policies are respected. Users without a mail attribute are listed with Result = No email.
#>
    [CmdletBinding(SupportsShouldProcess)]
    param(
        [Parameter(Mandatory)] [string]$SmtpServer,
        [Parameter(Mandatory)] [string]$From,
        [int]$DaysBefore = 7,
        [string]$SearchBase,
        [string]$LogPath,
        [string]$TestRecipient
    )
    $p = @{ Filter = 'Enabled -eq $true -and PasswordNeverExpires -eq $false'; Properties = 'mail', 'DisplayName', 'msDS-UserPasswordExpiryTimeComputed' }
    if ($SearchBase) { $p.SearchBase = $SearchBase }
    $now = Get-Date
    $rows = foreach ($u in @(Get-ADUser @p)) {
        $raw = $u.'msDS-UserPasswordExpiryTimeComputed'
        if (-not $raw -or $raw -ge 9223372036854775807) { continue }
        $exp = [datetime]::FromFileTime($raw)
        $days = [math]::Floor(($exp - $now).TotalDays)
        if ($days -lt 0 -or $days -gt $DaysBefore) { continue }
        $to = if ($TestRecipient) { $TestRecipient } else { $u.mail }
        $result = 'Preview'
        if (-not $to) { $result = 'No email' }
        elseif ($PSCmdlet.ShouldProcess($to, "Password expiry notice for $($u.SamAccountName) ($days days)")) {
            $when = if ($days -eq 0) { 'today' } elseif ($days -eq 1) { 'tomorrow' } else { "in $days days" }
            $body = "<p>Hello $($u.DisplayName),</p><p>Your network password expires <b>$when</b> ($($exp.ToString('dddd d MMMM yyyy HH:mm'))).</p><p>Press Ctrl+Alt+Del and choose <i>Change a password</i> before then.</p><p>IT Support</p>"
            try { Send-MailMessage -SmtpServer $SmtpServer -From $From -To $to -Subject "Your password expires $when" -Body $body -BodyAsHtml -ErrorAction Stop; $result = 'Sent' }
            catch { $result = "Failed: $($_.Exception.Message)" }
        }
        [pscustomobject]@{ User = $u.SamAccountName; Name = $u.DisplayName; Email = $u.mail; Expires = $exp; DaysLeft = $days; Result = $result; Time = $now }
    }
    $rows = @($rows)
    if ($LogPath -and $rows.Count -and $PSCmdlet.ShouldProcess($LogPath, 'Append log')) { $rows | Export-Csv -Path $LogPath -Append -NoTypeInformation }
    $rows
}

function Get-PasswordExpiry {
<#
.SYNOPSIS
Users whose passwords expire within a number of days (fine-grained policies included).
.DESCRIPTION
Reads msDS-UserPasswordExpiryTimeComputed, which already accounts for PSOs, so no policy
maths is needed. Accounts set to never expire are skipped.
.PARAMETER DaysAhead
Expiring within this many days. Use a negative number to list already-expired passwords too.
.PARAMETER SearchBase
Only users under this OU (distinguished name).
.PARAMETER Server
Domain or DC to ask.
.EXAMPLE
Get-PasswordExpiry -DaysAhead 14 -SearchBase 'OU=Staff,DC=contoso,DC=com'
#>
    [CmdletBinding()]
    param(
        [int]$DaysAhead = 14,
        [string]$SearchBase,
        [string]$Server
    )
    $p = @{ Filter = 'Enabled -eq $true -and PasswordNeverExpires -eq $false'; Properties = 'msDS-UserPasswordExpiryTimeComputed', 'mail', 'DisplayName', 'PasswordLastSet' }
    if ($SearchBase) { $p.SearchBase = $SearchBase }
    if ($Server) { $p.Server = $Server }
    $now = Get-Date
    Get-ADUser @p | ForEach-Object {
        $raw = $_.'msDS-UserPasswordExpiryTimeComputed'
        if (-not $raw -or $raw -ge 9223372036854775807) { return }
        $exp = [datetime]::FromFileTime($raw)
        $days = [math]::Floor(($exp - $now).TotalDays)
        if ($days -le $DaysAhead) {
            [pscustomobject]@{ User = $_.SamAccountName; DisplayName = $_.DisplayName; Mail = $_.mail; PasswordLastSet = $_.PasswordLastSet; Expires = $exp; DaysLeft = $days }
        }
    } | Sort-Object DaysLeft
}

function Compare-ADUser {
<#
.SYNOPSIS
Side-by-side differences between two accounts: account options, logon restrictions, UPN/mail, and group memberships.
.DESCRIPTION
For "the new user can't log in but the user we copied works": shows a pending password change,
Log On To (workstation) lists, logon hours, expiry, UPN or mail mismatches and missing groups.
.PARAMETER User
The account with the problem.
.PARAMETER ReferenceUser
A similar account that works.
.PARAMETER Server
Domain or DC.
.EXAMPLE
Compare-ADUser -User newuser -ReferenceUser workinguser
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string]$User, [Parameter(Mandatory)] [string]$ReferenceUser, [string]$Server)
    $props = 'UserPrincipalName', 'mail', 'Enabled', 'LockedOut', 'PasswordExpired', 'PasswordNeverExpires', 'CannotChangePassword', 'pwdLastSet', 'AccountExpirationDate', 'userWorkstations', 'logonHours', 'SmartcardLogonRequired', 'AccountNotDelegated', 'TrustedForDelegation', 'Description', 'DistinguishedName', 'MemberOf', 'msDS-UserPasswordExpiryTimeComputed', 'proxyAddresses'
    $p = @{ Properties = $props }
    if ($Server) { $p.Server = $Server }
    $a = Get-ADUser -Identity $User @p
    $b = Get-ADUser -Identity $ReferenceUser @p
    $show = {
        param($o, $n)
        $v = $o.$n
        if ($n -eq 'pwdLastSet') { if ($v -eq 0) { return 'MUST CHANGE AT NEXT LOGON' } else { return [datetime]::FromFileTime($v) } }
        if ($n -eq 'logonHours') { if ($v) { return ([BitConverter]::ToString([byte[]]$v)) } else { return '(all hours)' } }
        if ($n -eq 'msDS-UserPasswordExpiryTimeComputed') { if ($v -and $v -lt 9223372036854775807) { return [datetime]::FromFileTime($v) } else { return '(never)' } }
        if ($n -eq 'DistinguishedName') { return ($v -replace '^CN=[^,]+,', '') }
        if ($v -is [System.Collections.IEnumerable] -and -not ($v -is [string])) { return (@($v) -join '; ') }
        return [string]$v
    }
    foreach ($n in ($props | Where-Object { $_ -ne 'MemberOf' })) {
        $va = [string](& $show $a $n); $vb = [string](& $show $b $n)
        [pscustomobject]@{ Setting = $(if ($n -eq 'DistinguishedName') { 'OU' } else { $n }); $User = $va; $ReferenceUser = $vb; Different = ($va -ne $vb) }
    }
    $ga = @($a.MemberOf | ForEach-Object { ($_ -split ',')[0] -replace '^CN=' })
    $gb = @($b.MemberOf | ForEach-Object { ($_ -split ',')[0] -replace '^CN=' })
    foreach ($g in ($gb | Where-Object { $ga -notcontains $_ })) { [pscustomobject]@{ Setting = 'Group'; $User = '(missing)'; $ReferenceUser = $g; Different = $true } }
    foreach ($g in ($ga | Where-Object { $gb -notcontains $_ })) { [pscustomobject]@{ Setting = 'Group'; $User = $g; $ReferenceUser = '(not in)'; Different = $true } }
}

