function Get-CrossDomainUser {
<#
.SYNOPSIS
Lists user accounts from one or more domains (across a trust) in one table.
.PARAMETER Domain
Domains to query, one per line. The trust and DNS must work for the other domains.
.PARAMETER Credential
Account for the other domain, if your own account has no rights there.
.PARAMETER EnabledOnly
Only enabled accounts.
.EXAMPLE
Get-CrossDomainUser -Domain domain1.com, domain2.ads -EnabledOnly
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)] [string[]]$Domain,
        [pscredential]$Credential,
        [switch]$EnabledOnly
    )
    foreach ($d in $Domain) {
        $p = @{ Filter = '*'; Server = $d; Properties = 'DisplayName', 'Enabled', 'LastLogonDate', 'EmailAddress' }
        if ($EnabledOnly) { $p.Filter = 'Enabled -eq $true' }
        if ($Credential) { $p.Credential = $Credential }
        Get-ADUser @p | Select-Object @{ N = 'Domain'; E = { $d } }, SamAccountName, DisplayName, Enabled, LastLogonDate, EmailAddress
    }
}

function Get-CertificateFileInfo {
<#
.SYNOPSIS
Subject, issuer, validity dates and thumbprint of a .cer, .crt or .pfx file - no keytool needed.
.PARAMETER Path
Certificate file.
.PARAMETER Password
Password for a .pfx, if it has one.
.EXAMPLE
Get-CertificateFileInfo -Path 'C:\Program Files\Inductive Automation\Ignition\data\opcua\client\security\certificates.pfx'
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string]$Path, [securestring]$Password)
    $col = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2Collection
    $flags = [System.Security.Cryptography.X509Certificates.X509KeyStorageFlags]::DefaultKeySet
    if ($Password) { $col.Import((Resolve-Path -LiteralPath $Path).ProviderPath, $Password, $flags) }
    else {
        try { $col.Import((Resolve-Path -LiteralPath $Path).ProviderPath) }
        catch { $col.Import((Resolve-Path -LiteralPath $Path).ProviderPath, '', $flags) }
    }
    $now = Get-Date
    foreach ($c in $col) {
        [pscustomobject]@{
            File      = Split-Path -Path $Path -Leaf
            Subject   = $c.Subject
            Issuer    = $c.Issuer
            NotBefore = $c.NotBefore
            NotAfter  = $c.NotAfter
            DaysLeft  = [math]::Floor(($c.NotAfter - $now).TotalDays)
            Status    = $(if ($c.NotAfter -lt $now) { 'EXPIRED' } elseif ($c.NotBefore -gt $now) { 'Not yet valid' } else { 'Valid dates' })
            SelfSigned = ($c.Subject -eq $c.Issuer)
            Thumbprint = $c.Thumbprint
        }
    }
}

function Get-JavaKeystoreEntry {
<#
.SYNOPSIS
Lists the certificates in a Java keystore (cacerts, .jks or .pfx) with keytool: alias, owner, issuer and validity.
.PARAMETER Keystore
Keystore file. For a JRE truststore: <jre>\lib\security\cacerts.
.PARAMETER KeytoolPath
keytool.exe to use. Empty = searched under Ignition's bundled JRE, then JAVA_HOME, then PATH.
.PARAMETER StorePassword
Keystore password (cacerts default is "changeit"; Ignition's own keystores are often blank).
.PARAMETER Alias
Only this alias.
.EXAMPLE
Get-JavaKeystoreEntry -Keystore 'C:\Program Files\Inductive Automation\Ignition\lib\runtime\jre-win\lib\security\cacerts' -StorePassword <secure> -Alias inmdc01-ca
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)] [string]$Keystore,
        [string]$KeytoolPath,
        [securestring]$StorePassword,
        [string]$Alias
    )
    if (-not $KeytoolPath) {
        $cands = @(Get-ChildItem 'C:\Program Files\Inductive Automation\Ignition\lib\runtime' -Recurse -Filter keytool.exe -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName })
        if ($env:JAVA_HOME) { $cands += Join-Path $env:JAVA_HOME 'bin\keytool.exe' }
        $onPath = Get-Command keytool.exe -ErrorAction SilentlyContinue
        if ($onPath) { $cands += $onPath.Source }
        $KeytoolPath = @($cands | Where-Object { $_ -and (Test-Path $_) }) | Select-Object -First 1
        if (-not $KeytoolPath) { throw 'keytool.exe not found. Give -KeytoolPath (it is in <jre>\bin).' }
    }
    $pw = ''
    if ($StorePassword) { $pw = (New-Object System.Management.Automation.PSCredential('x', $StorePassword)).GetNetworkCredential().Password }
    $args2 = @('-list', '-v', '-keystore', $Keystore, '-storepass', $pw)
    if ($Keystore -match '\.(pfx|p12)$') { $args2 += @('-storetype', 'PKCS12') }
    if ($Alias) { $args2 += @('-alias', $Alias) }
    $out = @(& $KeytoolPath @args2 2>&1 | ForEach-Object { [string]$_ })
    if ($LASTEXITCODE -ne 0) { throw "keytool failed: $(($out | Select-Object -First 3) -join ' ')" }
    $cur = $null
    foreach ($l in $out) {
        if ($l -match '^Alias name: (.+)$') { if ($cur) { [pscustomobject]$cur }; $cur = [ordered]@{ Alias = $Matches[1]; Owner = ''; Issuer = ''; ValidFrom = ''; ValidUntil = ''; Expired = $null } }
        elseif ($cur -and $l -match '^Owner: (.+)$' -and -not $cur.Owner) { $cur.Owner = $Matches[1] }
        elseif ($cur -and $l -match '^Issuer: (.+)$' -and -not $cur.Issuer) { $cur.Issuer = $Matches[1] }
        elseif ($cur -and $l -match '^Valid from: (.+) until: (.+)$' -and -not $cur.ValidUntil) {
            $cur.ValidFrom = $Matches[1]; $cur.ValidUntil = $Matches[2]
            $d = $null
            $u = ($Matches[2] -replace '^\w{3} ', '') -replace ' [A-Z]{2,5} ', ' '
            try { $d = [datetime]::ParseExact($u, 'MMM dd HH:mm:ss yyyy', [Globalization.CultureInfo]::InvariantCulture) } catch { }
            if ($d) { $cur.Expired = ($d -lt (Get-Date)) }
        }
    }
    if ($cur) { [pscustomobject]$cur }
}

