function Get-DcSrvRecord {
<#
.SYNOPSIS
The DC SRV records DNS returns for a domain (LDAP, Kerberos, GC), with each DC's IP.
.PARAMETER Domain
Domain to look up.
.PARAMETER Server
DNS server to ask. Empty = this computer's DNS servers.
.EXAMPLE
Get-DcSrvRecord -Domain domain2.ads
.NOTES
If these come back empty from one side of a trust, check the conditional forwarder or
secondary zone for the other domain.
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)] [string]$Domain,
        [string]$Server
    )
    foreach ($svc in '_ldap._tcp', '_kerberos._tcp', '_gc._tcp') {
        $p = @{ Name = "$svc.$Domain"; Type = 'SRV'; ErrorAction = 'SilentlyContinue' }
        if ($Server) { $p.Server = $Server }
        $recs = @(Resolve-DnsName @p | Where-Object { $_.QueryType -eq 'SRV' })
        if ($recs.Count -eq 0) { [pscustomobject]@{ Record = $svc; Target = '(none)'; Port = $null; IPAddress = '' }; continue }
        foreach ($r in $recs) {
            $a = @{ Name = $r.NameTarget; Type = 'A'; ErrorAction = 'SilentlyContinue' }
            if ($Server) { $a.Server = $Server }
            $ip = (@(Resolve-DnsName @a | Where-Object { $_.IPAddress }) | ForEach-Object { $_.IPAddress }) -join ', '
            [pscustomobject]@{ Record = $svc; Target = $r.NameTarget; Port = $r.Port; Priority = $r.Priority; IPAddress = $ip }
        }
    }
}

function Measure-DnsLookup {
<#
.SYNOPSIS
Resolves a name several times and reports how long each lookup took, which DNS server answered and what came back.
.PARAMETER Name
Name to resolve, e.g. _ldap._tcp.dc._msdcs.otherforest.com.
.PARAMETER Type
Record type.
.PARAMETER Server
DNS server to ask. Empty = this computer's DNS servers (listed in the output).
.PARAMETER Count
How many times.
.EXAMPLE
Measure-DnsLookup -Name _ldap._tcp.dc._msdcs.domain2.ads -Type SRV
.NOTES
Seconds instead of milliseconds, or a timeout, points to a missing or broken conditional forwarder.
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string]$Name, [ValidateSet('A', 'AAAA', 'SRV', 'PTR', 'CNAME', 'MX', 'TXT', 'NS', 'SOA')] [string]$Type = 'A', [string]$Server, [int]$Count = 3)
    $servers = if ($Server) { $Server } else { ((@(Get-DnsClientServerAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.ServerAddresses }) | ForEach-Object { $_.ServerAddresses }) | Select-Object -Unique) -join ', ' }
    for ($i = 1; $i -le $Count; $i++) {
        $p = @{ Name = $Name; Type = $Type; DnsOnly = $true; NoHostsFile = $true; ErrorAction = 'Stop' }
        if ($Server) { $p.Server = $Server }
        if ($i -gt 1) { Clear-DnsClientCache -ErrorAction SilentlyContinue }
        $sw = [Diagnostics.Stopwatch]::StartNew()
        try {
            $r = @(Resolve-DnsName @p)
            $ans = @($r | Where-Object { $_.Section -eq 'Answer' } | ForEach-Object { if ($_.IPAddress) { $_.IPAddress } elseif ($_.NameTarget) { $_.NameTarget } elseif ($_.NameHost) { $_.NameHost } else { $_.Name } })
            [pscustomobject]@{ Try = $i; Name = $Name; Type = $Type; Ms = $sw.ElapsedMilliseconds; Result = 'OK'; Answers = ($ans -join ', '); DnsServers = $servers }
        }
        catch { [pscustomobject]@{ Try = $i; Name = $Name; Type = $Type; Ms = $sw.ElapsedMilliseconds; Result = $_.Exception.Message; Answers = ''; DnsServers = $servers } }
    }
}

function Test-ReverseDns {
<#
.SYNOPSIS
Checks that IP addresses have reverse (PTR) records - missing PTRs slow down logons.
.PARAMETER IPAddress
Addresses to check, one per line.
.PARAMETER Server
DNS server to ask. Empty = this computer's DNS servers.
.EXAMPLE
Test-ReverseDns -IPAddress 10.40.50.6, 10.40.50.7
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)] [string[]]$IPAddress,
        [string]$Server
    )
    foreach ($ip in $IPAddress) {
        $p = @{ Name = $ip; Type = 'PTR'; ErrorAction = 'Stop' }
        if ($Server) { $p.Server = $Server }
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        try {
            $r = @(Resolve-DnsName @p | Where-Object { $_.NameHost })
            [pscustomobject]@{ IPAddress = $ip; Name = (($r | ForEach-Object { $_.NameHost }) -join ', '); Found = ($r.Count -gt 0); Ms = $sw.ElapsedMilliseconds; Error = '' }
        }
        catch { [pscustomobject]@{ IPAddress = $ip; Name = ''; Found = $false; Ms = $sw.ElapsedMilliseconds; Error = $_.Exception.Message } }
    }
}

function Find-StaleDcSrvRecord {
<#
.SYNOPSIS
Compares the DCs DNS advertises (_ldap._tcp.dc._msdcs.<domain>) with the real DC list - a record for a retired DC makes logons hang on it.
.PARAMETER Domain
Domain to check.
.EXAMPLE
Find-StaleDcSrvRecord -Domain domain2.ads
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string]$Domain)
    $srv = @(Resolve-DnsName -Name "_ldap._tcp.dc._msdcs.$Domain" -Type SRV -ErrorAction Stop | Where-Object { $_.Type -eq 'SRV' } | ForEach-Object { $_.NameTarget.TrimEnd('.').ToLower() } | Sort-Object -Unique)
    $live = @()
    try { $live = @(Get-ADDomainController -Filter * -Server $Domain -ErrorAction Stop | ForEach-Object { $_.HostName.ToLower() }) }
    catch { $live = @(nltest /dclist:$Domain 2>$null | ForEach-Object { if ([string]$_ -match '^\s+(\S+\.\S+)') { $Matches[1].ToLower() } }) }
    foreach ($h in $srv) {
        $resolves = $true; $ip = ''
        try { $ip = (@(Resolve-DnsName $h -Type A -ErrorAction Stop | Where-Object IPAddress) | ForEach-Object { $_.IPAddress }) -join ', ' } catch { $resolves = $false }
        $answers = $false
        if ($resolves) { $t = New-Object System.Net.Sockets.TcpClient; try { $iar = $t.BeginConnect($h, 389, $null, $null); $answers = $iar.AsyncWaitHandle.WaitOne(2000) -and $t.Connected } catch { } finally { $t.Close() } }
        [pscustomobject]@{
            Advertised = $h; IPAddress = $ip; InDcList = ($live -contains $h); Ldap389 = $answers
            Status = $(if (-not ($live -contains $h) -and -not $answers) { 'STALE - remove from DNS' } elseif (-not ($live -contains $h)) { 'Review - answers but not in DC list' } elseif (-not $answers) { 'DC not answering on 389' } else { 'OK' })
        }
    }
}

function Get-AdSiteSubnet {
<#
.SYNOPSIS
The AD sites and the subnets mapped to them, and whether this computer's own IP falls in a mapped subnet.
.PARAMETER Server
Domain or DC.
.EXAMPLE
Get-AdSiteSubnet -Server domain2.ads
.NOTES
A client subnet that is not mapped to a site makes DC Locator try DCs one by one - a classic slow-logon cause across trusts.
#>
    [CmdletBinding()]
    param([string]$Server)
    $p = @{ Filter = '*' }
    if ($Server) { $p.Server = $Server }
    $mine = @(Get-NetIPAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -notlike '127.*' -and $_.IPAddress -notlike '169.254*' } | ForEach-Object { $_.IPAddress })
    $toInt = { param($ip) $b = ([System.Net.IPAddress]::Parse($ip)).GetAddressBytes(); [Array]::Reverse($b); [BitConverter]::ToUInt32($b, 0) }
    foreach ($s in @(Get-ADReplicationSubnet @p -Properties Site, Location)) {
        $net, $len = $s.Name -split '/'
        $covers = @()
        if ($net -match '^\d+\.\d+\.\d+\.\d+$') {
            $mask = if ([int]$len -eq 0) { [uint32]0 } else { [uint32]([math]::Pow(2, 32) - [math]::Pow(2, 32 - [int]$len)) }
            foreach ($ip in $mine) { if (((& $toInt $ip) -band $mask) -eq ((& $toInt $net) -band $mask)) { $covers += $ip } }
        }
        [pscustomobject]@{ Subnet = $s.Name; Site = (([string]$s.Site -split ',')[0] -replace '^CN='); Location = $s.Location; ThisComputer = ($covers -join ', ') }
    }
    if ($mine.Count) { Write-Verbose "This computer: $($mine -join ', ')" }
}

function Test-ADWebService {
<#
.SYNOPSIS
Why "Unable to contact the server ... Active Directory Web Services" happens: checks port 9389 from here, and the ADWS service on the DC.
.PARAMETER ComputerName
Domain controllers, one per line.
.EXAMPLE
Test-ADWebService -ComputerName dc1.domain2.ads
.NOTES
ADWS is only for the AD PowerShell module and admin tools - a closed 9389 does not slow down logons.
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string[]]$ComputerName)
    foreach ($c in $ComputerName) {
        $open = $false
        $tcp = New-Object System.Net.Sockets.TcpClient
        try { $iar = $tcp.BeginConnect($c, 9389, $null, $null); $open = $iar.AsyncWaitHandle.WaitOne(3000) -and $tcp.Connected } catch { } finally { $tcp.Close() }
        $svc = $null
        try { $svc = Get-Service -Name ADWS -ComputerName $c -ErrorAction Stop } catch { }
        [pscustomobject]@{ DC = $c; Port9389Open = $open; ADWSService = $(if ($svc) { [string]$svc.Status } else { '(could not query - RPC blocked or no rights)' }); Hint = $(if (-not $open -and $svc -and $svc.Status -eq 'Running') { 'Service runs but 9389 is blocked - firewall rule "Active Directory Web Services (TCP-In)" or a network firewall.' } elseif ($svc -and $svc.Status -ne 'Running') { 'Start the ADWS service on the DC.' } else { '' }) }
    }
}

function Get-DcHealthReport {
<#
.SYNOPSIS
For every DC of one or more domains: forward DNS, reverse DNS (PTR), the AD ports and the clock offset - the usual causes of slow logons across a trust.
.PARAMETER Domain
Domains, one per line.
.PARAMETER TimeoutMs
Port test timeout.
.EXAMPLE
Get-DcHealthReport -Domain domain1.com, domain2.ads
.NOTES
Look for PTR = MISSING, any port = False, or an offset over a few seconds. Falls back to nltest if AD Web Services is unreachable.
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string[]]$Domain, [int]$TimeoutMs = 2000)
    $ports = [ordered]@{ LDAP = 389; LDAPS = 636; Kerberos = 88; SMB = 445; RPC = 135; GC = 3268; ADWS = 9389 }
    foreach ($d in $Domain) {
        $dcs = @()
        try { $dcs = @(Get-ADDomainController -Filter * -Server $d -ErrorAction Stop | ForEach-Object { [pscustomobject]@{ Host = $_.HostName; IP = $_.IPv4Address; Site = $_.Site } }) }
        catch {
            Write-Warning "$d : Get-ADDomainController failed - using nltest."
            $dcs = @(nltest /dclist:$d 2>$null | ForEach-Object { if ([string]$_ -match '^\s+(\S+\.\S+)') { [pscustomobject]@{ Host = $Matches[1]; IP = ''; Site = '' } } })
        }
        foreach ($dc in $dcs) {
            $ip = $dc.IP
            if (-not $ip) { try { $ip = (@(Resolve-DnsName $dc.Host -Type A -ErrorAction Stop | Where-Object IPAddress) | Select-Object -First 1).IPAddress } catch { $ip = '' } }
            $ptr = 'N/A'
            if ($ip) { try { $ptr = (@(Resolve-DnsName -Name $ip -Type PTR -ErrorAction Stop) | ForEach-Object { $_.NameHost }) -join ';' } catch { $ptr = 'MISSING' } }
            $row = [ordered]@{ Domain = $d; DC = $dc.Host; IPAddress = $ip; Site = $dc.Site; PTR = $ptr }
            foreach ($k in $ports.Keys) {
                $t = New-Object System.Net.Sockets.TcpClient
                $ok = $false
                try { $iar = $t.BeginConnect($dc.Host, $ports[$k], $null, $null); $ok = $iar.AsyncWaitHandle.WaitOne($TimeoutMs) -and $t.Connected } catch { } finally { $t.Close() }
                $row["$k`_$($ports[$k])"] = $ok
            }
            $off = $null
            $w = @(w32tm /stripchart /computer:$($dc.Host) /samples:1 /dataonly 2>&1 | ForEach-Object { [string]$_ })
            foreach ($l in $w) { if ($l -match ',\s*([+-]?\d+(\.\d+)?)s') { $off = [double]$Matches[1] } }
            $row['OffsetSec'] = $off
            [pscustomobject]$row
        }
    }
}

function Get-DomainControllerList {
<#
.SYNOPSIS
Every domain controller of one or more domains, with IP address and site.
.DESCRIPTION
Uses Get-ADDomainController. If AD Web Services cannot be reached for a domain, falls back
to nltest /dclist plus a DNS lookup for each DC.
.PARAMETER Domain
Domains, one per line. Empty = the current domain.
.EXAMPLE
Get-DomainControllerList -Domain domain1.com, domain2.ads
#>
    [CmdletBinding()]
    param([string[]]$Domain)
    if (-not $Domain) { $Domain = @($env:USERDNSDOMAIN) }
    foreach ($d in $Domain) {
        try {
            Get-ADDomainController -Filter * -Server $d -ErrorAction Stop |
                Select-Object @{ N = 'Domain'; E = { $d } }, Name, HostName, IPv4Address, Site, IsGlobalCatalog, OperatingSystem
        }
        catch {
            Write-Warning "$d : AD Web Services not reachable ($($_.Exception.Message)) - using nltest + DNS."
            $lines = nltest /dclist:$d 2>&1
            foreach ($l in $lines) {
                if ([string]$l -notmatch '^\s+(\S+\.\S+)') { continue }
                $name = $Matches[1]
                $ip = (Resolve-DnsName $name -Type A -ErrorAction SilentlyContinue | Select-Object -First 1).IPAddress
                [pscustomobject]@{ Domain = $d; Name = $name.Split('.')[0]; HostName = $name; IPv4Address = $ip; Site = ''; IsGlobalCatalog = ([string]$l -match '\[GC\]'); OperatingSystem = '' }
            }
        }
    }
}

function Test-DcPort {
<#
.SYNOPSIS
Tests the ports a domain controller needs (LDAP, Kerberos, SMB, RPC, GC ...) from this computer.
.PARAMETER ComputerName
DCs (or any servers) to test, one per line.
.PARAMETER Port
Ports to test. Default: 53 DNS, 88 Kerberos, 135 RPC, 389 LDAP, 445 SMB, 464 kpasswd, 636 LDAPS, 3268 GC, 3269 GC-SSL, 9389 ADWS.
.EXAMPLE
Test-DcPort -ComputerName dc1.domain2.ads
.NOTES
RPC also needs the dynamic range (49152-65535 by default) open between the sites. UDP
(DNS, Kerberos, NTP 123) is not tested by Test-NetConnection.
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)] [string[]]$ComputerName,
        [int[]]$Port = @(53, 88, 135, 389, 445, 464, 636, 3268, 3269, 9389)
    )
    $names = @{ 53 = 'DNS'; 88 = 'Kerberos'; 135 = 'RPC endpoint mapper'; 389 = 'LDAP'; 445 = 'SMB'; 464 = 'Kerberos password'; 636 = 'LDAPS'; 3268 = 'Global Catalog'; 3269 = 'Global Catalog SSL'; 9389 = 'AD Web Services'; 5985 = 'WinRM'; 3389 = 'RDP' }
    $old = $ProgressPreference; $ProgressPreference = 'SilentlyContinue'
    try {
        foreach ($c in $ComputerName) {
            foreach ($p in $Port) {
                $sw = [System.Diagnostics.Stopwatch]::StartNew()
                $r = Test-NetConnection -ComputerName $c -Port $p -WarningAction SilentlyContinue
                [pscustomobject]@{
                    Computer = $c; Port = $p; Service = $names[$p]; Open = [bool]$r.TcpTestSucceeded
                    RemoteAddress = $r.RemoteAddress; Ms = $sw.ElapsedMilliseconds
                }
            }
        }
    }
    finally { $ProgressPreference = $old }
}

function Invoke-DcDiag {
<#
.SYNOPSIS
Runs dcdiag tests and lists each test with passed / failed, plus the failure lines.
.PARAMETER Test
Tests to run, e.g. DNS, Trusts, Replications, Advertising, FsmoCheck, NetLogons. Empty = the default set.
.PARAMETER Server
DC to test. Empty = this computer.
.EXAMPLE
Invoke-DcDiag -Test DNS, Trusts
#>
    [CmdletBinding()]
    param([string[]]$Test = @(), [string]$Server)
    $a = @()
    if ($Server) { $a += "/s:$Server" }
    foreach ($t in $Test) { $a += "/test:$t" }
    if ($Test -contains 'DNS') { $a += '/v' }
    $out = @(dcdiag @a 2>&1 | ForEach-Object { [string]$_ })
    $current = ''
    $fails = @{}
    foreach ($l in $out) {
        if ($l -match 'Starting test:\s*(\S+)') { $current = $Matches[1]; $fails[$current] = @() }
        elseif ($current -and $l -match 'error|fail|warning' -and $l -notmatch 'passed test') { $fails[$current] += $l.Trim() }
        if ($l -match '\.+\s*(\S+)\s+(passed|failed) test\s+(\S+)') {
            [pscustomobject]@{ Target = $Matches[1]; Test = $Matches[3]; Result = $Matches[2]; Details = $(if ($Matches[2] -eq 'failed' -and $fails.ContainsKey($Matches[3])) { (@($fails[$Matches[3]]) | Select-Object -First 5) -join ' | ' } else { '' }) }
        }
    }
}

function Test-SecureChannel {
<#
.SYNOPSIS
Tests the computer's secure channel to its domain (optionally against one DC), with nltest /sc_query detail.
.PARAMETER Server
DC to test against. Empty = any.
.EXAMPLE
Test-SecureChannel -Server dc1.contoso.com
.NOTES
To repair (elevated, with a domain admin credential): Test-ComputerSecureChannel -Repair -Credential (Get-Credential)
#>
    [CmdletBinding()]
    param([string]$Server)
    $p = @{}
    if ($Server) { $p.Server = $Server }
    $ok = $false; $err = ''
    try { $ok = Test-ComputerSecureChannel @p -ErrorAction Stop } catch { $err = $_.Exception.Message }
    $q = (@(nltest /sc_query:$env:USERDNSDOMAIN 2>&1) | ForEach-Object { ([string]$_).Trim() } | Where-Object { $_ }) -join ' | '
    [pscustomobject]@{ Computer = $env:COMPUTERNAME; Domain = $env:USERDNSDOMAIN; SecureChannelOK = $ok; Error = $err; NltestScQuery = $q }
}

function Test-DomainTrust {
<#
.SYNOPSIS
Checks a trust from this side: can a DC in the other domain be found, and is the secure channel healthy.
.PARAMETER TrustedDomain
The other domain.
.PARAMETER Verify
Also run netdom trust /verify (needs domain admin rights on both sides).
.PARAMETER LocalDomain
This side's domain, for netdom. Empty = current domain.
.EXAMPLE
Test-DomainTrust -TrustedDomain domain2.ads
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)] [string]$TrustedDomain,
        [switch]$Verify,
        [string]$LocalDomain
    )
    if (-not $LocalDomain) { $LocalDomain = $env:USERDNSDOMAIN }
    $checks = @(
        @{ Name = 'Locate a DC (nltest /dsgetdc)'; Run = { nltest /dsgetdc:$TrustedDomain 2>&1 } }
        @{ Name = 'Secure channel (nltest /sc_query)'; Run = { nltest /sc_query:$TrustedDomain 2>&1 } }
        @{ Name = 'Trusted domains (nltest /domain_trusts)'; Run = { nltest /domain_trusts 2>&1 } }
    )
    if ($Verify) { $checks += @{ Name = 'netdom trust /verify'; Run = { netdom trust $LocalDomain /domain:$TrustedDomain /verify 2>&1 } } }
    foreach ($c in $checks) {
        $out = @(& $c.Run | ForEach-Object { [string]$_ })
        [pscustomobject]@{
            Check  = $c.Name
            Result = $(if ($LASTEXITCODE -eq 0) { 'OK' } else { "Failed (exit $LASTEXITCODE)" })
            Output = (($out | Where-Object { $_.Trim() }) -join ' | ')
        }
    }
}

function Get-DomainTrustInfo {
<#
.SYNOPSIS
The trusts of a domain: partner, direction (two-way, inbound, outbound), type and selective authentication - with an nltest fallback when AD Web Services is not reachable.
.PARAMETER Server
Domain or DC to ask. Run it for both domains to compare.
.EXAMPLE
Get-DomainTrustInfo -Server domain1.com
#>
    [CmdletBinding()]
    param([string]$Server = $env:USERDNSDOMAIN)
    try {
        Get-ADTrust -Filter * -Server $Server -ErrorAction Stop |
            Select-Object @{ N = 'Domain'; E = { $Server } }, @{ N = 'Partner'; E = { $_.Target } }, Direction, TrustType, ForestTransitive, SelectiveAuthentication, IntraForest, @{ N = 'Source'; E = { 'Get-ADTrust' } }
    }
    catch {
        Write-Warning "Get-ADTrust failed ($($_.Exception.Message)) - using nltest /domain_trusts."
        foreach ($l in @(nltest /domain_trusts /v 2>&1)) {
            if ([string]$l -match '^\s*\d+:\s+(\S+)\s+(\S+)?\s*\((.+)\)') {
                [pscustomobject]@{ Domain = $Server; Partner = $Matches[1]; Direction = $(if ($Matches[3] -match 'Direct Outbound' -and $Matches[3] -match 'Direct Inbound') { 'BiDirectional' } elseif ($Matches[3] -match 'Direct Outbound') { 'Outbound' } elseif ($Matches[3] -match 'Direct Inbound') { 'Inbound' } else { '' }); TrustType = $Matches[3]; ForestTransitive = $null; SelectiveAuthentication = $null; IntraForest = ($Matches[3] -match 'Forest Tree Root|Primary Domain'); Source = 'nltest' }
            }
        }
    }
}

function Get-LogonEvent {
<#
.SYNOPSIS
Successful logons (4624) with logon type, source address and the authentication package (Kerberos or NTLM).
.PARAMETER UserName
Only this account.
.PARAMETER Hours
How far back.
.PARAMETER IncludeService
Include service, batch and computer-account logons (usually noise).
.EXAMPLE
Get-LogonEvent -UserName jsmith -Hours 8
.NOTES
NTLM where you expected Kerberos usually means a DNS/SPN problem or a name typed as an IP address.
#>
    [CmdletBinding()]
    param([string]$UserName, [int]$Hours = 24, [switch]$IncludeService)
    $types = @{ '2' = 'Interactive'; '3' = 'Network'; '4' = 'Batch'; '5' = 'Service'; '7' = 'Unlock'; '8' = 'NetworkCleartext'; '9' = 'NewCredentials'; '10' = 'RemoteDesktop'; '11' = 'CachedInteractive' }
    Get-WinEvent -FilterHashtable @{ LogName = 'Security'; Id = 4624; StartTime = (Get-Date).AddHours(-$Hours) } -MaxEvents 2000 -ErrorAction SilentlyContinue |
        ForEach-Object {
            $x = [xml]$_.ToXml()
            $d = @{}
            foreach ($n in $x.Event.EventData.Data) { $d[$n.Name] = $n.'#text' }
            $user = [string]$d['TargetUserName']
            $lt = [string]$d['LogonType']
            if ($UserName -and $user -ne $UserName) { return }
            if (-not $IncludeService -and ($lt -in '4', '5' -or $user -like '*$' -or $user -in 'SYSTEM', 'LOCAL SERVICE', 'NETWORK SERVICE', 'ANONYMOUS LOGON', 'DWM-1', 'UMFD-0')) { return }
            [pscustomobject]@{ Time = $_.TimeCreated; User = "$($d['TargetDomainName'])\$user"; LogonType = $(if ($types.ContainsKey($lt)) { $types[$lt] } else { $lt }); From = $d['IpAddress']; Workstation = $d['WorkstationName']; Auth = $d['AuthenticationPackageName']; Process = $d['ProcessName'] }
        }
}

function Find-FolderAclEntry {
<#
.SYNOPSIS
Scans a folder tree for ACL entries that grant an account or group access (e.g. is this AD group still used on the share?).
.PARAMETER Path
Top folder to scan.
.PARAMETER Identity
Account or group name (DOMAIN\Group or just Group - matched as text), or a SID.
.PARAMETER Depth
How many folder levels below Path to check (folders only; files inherit).
.EXAMPLE
Find-FolderAclEntry -Path \\fileserver\shares -Identity 'CONTOSO\Finance-RW' -Depth 3
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)] [string]$Path,
        [Parameter(Mandatory)] [string]$Identity,
        [int]$Depth = 2
    )
    $folders = @(Get-Item -LiteralPath $Path -ErrorAction Stop) + @(Get-ChildItem -LiteralPath $Path -Directory -Recurse -Depth $Depth -ErrorAction SilentlyContinue)
    $needle = $Identity.ToLower()
    foreach ($f in $folders) {
        $acl = $null
        try { $acl = Get-Acl -LiteralPath $f.FullName -ErrorAction Stop } catch { continue }
        foreach ($a in $acl.Access) {
            $id = ([string]$a.IdentityReference).ToLower()
            if ($id -eq $needle -or $id.EndsWith('\' + $needle) -or $id -like "*$needle*") {
                [pscustomobject]@{ Folder = $f.FullName; Identity = [string]$a.IdentityReference; Rights = [string]$a.FileSystemRights; Type = [string]$a.AccessControlType; Inherited = $a.IsInherited }
            }
        }
    }
}

function Get-DriveMapping {
<#
.SYNOPSIS
Every drive letter: local disks, network drives (with their \\server\share), subst drives and boot-time mappings.
.EXAMPLE
Get-DriveMapping
.NOTES
A DisplayRoot like \\server\share means a network drive (per user, not available at boot).
#>
    [CmdletBinding()]
    param()
    $subst = @{}
    foreach ($line in @(subst 2>$null)) {
        if ([string]$line -match '^([A-Z]:)\\: => (.+)$') { $subst[$Matches[1]] = $Matches[2] }
    }
    $boot = @{}
    $dos = Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\DOS Devices' -ErrorAction SilentlyContinue
    if ($dos) { foreach ($p in $dos.PSObject.Properties) { if ($p.Name -match '^[A-Z]:$') { $boot[$p.Name] = ([string]$p.Value -replace '^\\\?\?\\', '') } } }
    $letters = @(Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue)
    foreach ($d in $letters) {
        $l = $d.Name + ':'
        $type = 'Local'
        if ($d.DisplayRoot -like '\\*') { $type = 'Network' }
        if ($subst.ContainsKey($l)) { $type = 'Subst (session)' }
        elseif ($boot.ContainsKey($l)) { $type = 'Subst (boot-time)' }
        [pscustomobject]@{
            Drive       = $l
            Type        = $type
            Target      = $(if ($subst.ContainsKey($l)) { $subst[$l] } elseif ($boot.ContainsKey($l)) { $boot[$l] } elseif ($d.DisplayRoot) { $d.DisplayRoot } else { $d.Root })
            FreeGB      = $(if ($null -ne $d.Free) { [math]::Round($d.Free / 1GB, 1) } else { $null })
            UsedGB      = $(if ($null -ne $d.Used) { [math]::Round($d.Used / 1GB, 1) } else { $null })
        }
    }
    foreach ($l in $boot.Keys) {
        if (-not ($letters | Where-Object { ($_.Name + ':') -eq $l })) {
            [pscustomobject]@{ Drive = $l; Type = 'Subst (boot-time, after reboot)'; Target = $boot[$l]; FreeGB = $null; UsedGB = $null }
        }
    }
}

function Find-UserProfileFile {
<#
.SYNOPSIS
Looks for the same relative path in every profile under C:\Users (e.g. each user's launcher JSON or a per-user exe).
.PARAMETER RelativePath
Path inside a profile, e.g. .ignition\clientlauncher-data\vision-client-launcher.json or AppData\Local\Google\Chrome\Application\chrome.exe.
.EXAMPLE
Find-UserProfileFile -RelativePath '.ignition\clientlauncher-data\vision-client-launcher.json'
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string]$RelativePath)
    foreach ($p in @(Get-ChildItem -Path "$env:SystemDrive\Users" -Directory -ErrorAction SilentlyContinue)) {
        $f = Join-Path $p.FullName $RelativePath
        if (Test-Path -LiteralPath $f) {
            $i = Get-Item -LiteralPath $f -Force
            [pscustomobject]@{ User = $p.Name; Path = $f; LastWriteTime = $i.LastWriteTime; Length = $(if ($i.PSIsContainer) { $null } else { $i.Length }); Version = $(if ($i.PSIsContainer) { '' } else { $i.VersionInfo.FileVersion }) }
        }
    }
}

function Rename-ItemAsOld {
<#
.SYNOPSIS
Renames a folder or file to <name>.old (or .old2, .old3 ... if that exists) so an install can start clean without deleting anything.
.PARAMETER Path
Folder or file.
.EXAMPLE
Rename-ItemAsOld -Path C:\AMS
.NOTES
One-liner: Rename-Item C:\AMS C:\AMS.old
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)] [string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) { throw "Not found: $Path" }
    $item = Get-Item -LiteralPath $Path
    $parent = Split-Path $item.FullName -Parent
    $new = "$($item.Name).old"; $i = 2
    while (Test-Path -LiteralPath (Join-Path $parent $new)) { $new = "$($item.Name).old$i"; $i++ }
    if ($PSCmdlet.ShouldProcess($item.FullName, "Rename to $new")) {
        Rename-Item -LiteralPath $item.FullName -NewName $new -ErrorAction Stop
        [pscustomobject]@{ Old = $item.FullName; New = (Join-Path $parent $new) }
    }
}

function Find-StartMenuShortcut {
<#
.SYNOPSIS
Shortcuts (.lnk) in the all-users and per-user Start menus and desktops whose name matches, with their targets.
.PARAMETER Name
Text in the shortcut name, e.g. AMS or Firefox.
.EXAMPLE
Find-StartMenuShortcut -Name AMS
#>
    [CmdletBinding()]
    param([string]$Name = '*')
    $roots = @("$env:ProgramData\Microsoft\Windows\Start Menu\Programs", "$env:PUBLIC\Desktop")
    $roots += @(Get-ChildItem "$env:SystemDrive\Users\*\AppData\Roaming\Microsoft\Windows\Start Menu\Programs" -Directory -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName })
    $roots += @(Get-ChildItem "$env:SystemDrive\Users\*\Desktop" -Directory -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName })
    $shell = New-Object -ComObject WScript.Shell
    foreach ($r in $roots) {
        foreach ($l in @(Get-ChildItem -Path $r -Recurse -Filter *.lnk -ErrorAction SilentlyContinue | Where-Object { $_.BaseName -like "*$Name*" })) {
            $t = $null
            try { $t = $shell.CreateShortcut($l.FullName) } catch { }
            [pscustomobject]@{ Shortcut = $l.BaseName; Target = $(if ($t) { $t.TargetPath } else { '' }); Arguments = $(if ($t) { $t.Arguments } else { '' }); Location = $l.DirectoryName }
        }
    }
}

function Mount-FolderAsDrive {
<#
.SYNOPSIS
Makes a folder look like the root of a drive (subst), optionally kept across reboots.
.DESCRIPTION
Without -Persistent this runs "subst X: <folder>" - the mapping lasts until logoff, and an
elevated window and a normal window see different subst drives.
With -Persistent it writes HKLM\SYSTEM\CurrentControlSet\Control\Session Manager\DOS Devices
"X:" = "\??\<folder>", which is created at boot for every session (elevated or not). Use it
when a setup must resume after a reboot from the same drive letter. It takes effect after
the next reboot. The folder must be on a local disk (not a network drive or USB stick).
.PARAMETER DriveLetter
Drive letter to create, e.g. X or X:.
.PARAMETER Path
Local folder to map.
.PARAMETER Persistent
Create it at every boot (registry), instead of for this session.
.EXAMPLE
Mount-FolderAsDrive -DriveLetter X -Path C:\EAInstall
.EXAMPLE
Mount-FolderAsDrive -DriveLetter K -Path C:\emerson_cd -Persistent
.NOTES
Remove it with Dismount-FolderDrive (same -Persistent switch).
#>
    [CmdletBinding(SupportsShouldProcess)]
    param(
        [Parameter(Mandatory)] [string]$DriveLetter,
        [Parameter(Mandatory)] [string]$Path,
        [switch]$Persistent
    )
    $letter = ($DriveLetter.Trim().TrimEnd(':', '\')).ToUpper() + ':'
    if ($letter -notmatch '^[A-Z]:$') { throw "Not a drive letter: $DriveLetter" }
    if (-not (Test-Path -LiteralPath $Path -PathType Container)) { throw "Folder not found: $Path" }
    $full = (Resolve-Path -LiteralPath $Path).ProviderPath.TrimEnd('\')
    if ($full -like '\\*') { throw 'A network path cannot be mapped this way. Copy the folder to a local disk first.' }
    if ($Persistent) {
        $key = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\DOS Devices'
        if ($PSCmdlet.ShouldProcess($letter, "Map to $full at every boot (registry)")) {
            New-ItemProperty -Path $key -Name $letter -Value ("\??\" + $full) -PropertyType String -Force | Out-Null
            [pscustomobject]@{ Drive = $letter; Folder = $full; Type = 'Persistent (registry)'; Note = 'Takes effect after a reboot. If a session subst for this letter exists, remove it first: subst ' + $letter + ' /d' }
        }
    }
    else {
        if ($PSCmdlet.ShouldProcess($letter, "subst to $full")) {
            $out = subst $letter $full 2>&1
            if ($LASTEXITCODE -ne 0) { throw "subst failed: $out" }
            [pscustomobject]@{ Drive = $letter; Folder = $full; Type = 'Session (subst)'; Note = 'Lasts until logoff; elevated and normal windows each have their own.' }
        }
    }
}

function Dismount-FolderDrive {
<#
.SYNOPSIS
Removes a drive letter made with subst, or the boot-time (registry) version of it.
.PARAMETER DriveLetter
Drive letter to remove.
.PARAMETER Persistent
Remove the registry (boot-time) mapping. Takes effect after the next reboot.
.EXAMPLE
Dismount-FolderDrive -DriveLetter X
.EXAMPLE
Dismount-FolderDrive -DriveLetter K -Persistent
#>
    [CmdletBinding(SupportsShouldProcess)]
    param(
        [Parameter(Mandatory)] [string]$DriveLetter,
        [switch]$Persistent
    )
    $letter = ($DriveLetter.Trim().TrimEnd(':', '\')).ToUpper() + ':'
    if ($Persistent) {
        $key = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\DOS Devices'
        if (-not (Get-ItemProperty -Path $key -Name $letter -ErrorAction SilentlyContinue)) { Write-Warning "No boot-time mapping for $letter."; return }
        if ($PSCmdlet.ShouldProcess($letter, 'Remove boot-time mapping')) {
            Remove-ItemProperty -Path $key -Name $letter
            [pscustomobject]@{ Drive = $letter; Removed = 'Registry mapping'; Note = 'Gone after the next reboot.' }
        }
    }
    else {
        if ($PSCmdlet.ShouldProcess($letter, 'subst /d')) {
            $out = subst $letter /d 2>&1
            [pscustomobject]@{ Drive = $letter; Removed = 'Session subst'; Note = [string]$out }
        }
    }
}

function Update-ComputerPolicy {
<#
.SYNOPSIS
Purges the computer's Kerberos tickets (so new group memberships count) and runs gpupdate /force, then shows the OU and applied GPOs.
.PARAMETER Reboot
Restart afterwards (some settings only apply at startup).
.EXAMPLE
Update-ComputerPolicy
.NOTES
After moving a computer between OUs, the move must reach the DC this computer uses (nltest /dsgetdc) before this helps. Some settings "tattoo" and stay after the policy is gone.
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([switch]$Reboot)
    if (-not $PSCmdlet.ShouldProcess($env:COMPUTERNAME, 'klist purge (computer) + gpupdate /force')) { return }
    $k = @(klist -li 0x3e7 purge 2>&1) -join ' '
    $g = @(gpupdate /force /wait:120 2>&1 | ForEach-Object { ([string]$_).Trim() } | Where-Object { $_ }) -join ' | '
    $r = @(gpresult /r /scope computer 2>&1 | ForEach-Object { [string]$_ })
    $ou = ($r | Where-Object { $_ -match 'CN=' } | Select-Object -First 1)
    $gpos = @()
    $in = $false
    foreach ($l in $r) {
        if ($l -match 'Applied Group Policy Objects') { $in = $true; continue }
        if ($in -and $l -match '^\s*-{3,}') { continue }
        if ($in -and $l -match '^\s{8,}\S') { $gpos += $l.Trim() } elseif ($in -and $l.Trim() -and $gpos.Count) { $in = $false }
    }
    [pscustomobject]@{ Computer = $env:COMPUTERNAME; KerberosPurge = $k.Trim(); GpUpdate = $g; ComputerOU = ([string]$ou).Trim(); AppliedGPOs = ($gpos -join ', ') }
    if ($Reboot) { Restart-Computer -Force }
}

