function Get-GpoLink {
<#
.SYNOPSIS
Every place a GPO is linked, whether the link is enabled or enforced, plus the GPO's status and security filtering.
.PARAMETER Name
GPO display name (wildcards allowed).
.PARAMETER Domain
Domain. Empty = current.
.EXAMPLE
Get-GpoLink -Name '*Local Admin*'
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string]$Name, [string]$Domain)
    $p = @{ All = $true }
    if ($Domain) { $p.Domain = $Domain }
    foreach ($g in @(Get-GPO @p | Where-Object { $_.DisplayName -like $Name })) {
        $rp = @{ Guid = $g.Id; ReportType = 'Xml' }
        if ($Domain) { $rp.Domain = $Domain }
        $x = [xml](Get-GPOReport @rp)
        $filter = @(Get-GPPermission -Guid $g.Id -All -ErrorAction SilentlyContinue | Where-Object { $_.Permission -eq 'GpoApply' } | ForEach-Object { $_.Trustee.Name }) -join ', '
        $links = @($x.GPO.LinksTo)
        if ($links.Count -eq 0 -or -not $links[0]) { [pscustomobject]@{ GPO = $g.DisplayName; Status = [string]$g.GpoStatus; LinkedTo = '(not linked)'; LinkEnabled = $null; Enforced = $null; AppliesTo = $filter; WmiFilter = [string]$g.WmiFilter.Name } }
        foreach ($l in $links) { if ($l) { [pscustomobject]@{ GPO = $g.DisplayName; Status = [string]$g.GpoStatus; LinkedTo = $l.SOMPath; LinkEnabled = $l.Enabled; Enforced = $l.NoOverride; AppliesTo = $filter; WmiFilter = [string]$g.WmiFilter.Name } } }
    }
}

function Find-GpoText {
<#
.SYNOPSIS
Finds which GPOs contain a piece of text anywhere in their settings.
.DESCRIPTION
Generates each GPO's XML report and searches it, so preferences, scripts, restricted groups
and registry settings are all covered. Slow on large domains (one report per GPO).
.PARAMETER Text
Text to look for, e.g. wkstn_ or a group name. Plain text, not a pattern.
.PARAMETER Domain
Domain whose GPOs to search. Empty = current domain.
.EXAMPLE
Find-GpoText -Text 'wkstn_'
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)] [string]$Text,
        [string]$Domain
    )
    $p = @{ All = $true }
    if ($Domain) { $p.Domain = $Domain }
    $gpos = @(Get-GPO @p)
    $i = 0
    foreach ($g in $gpos) {
        $i++
        Write-Progress -Activity 'Searching GPO reports' -Status $g.DisplayName -PercentComplete (100 * $i / [math]::Max(1, $gpos.Count))
        $rp = @{ Guid = $g.Id; ReportType = 'Xml' }
        if ($Domain) { $rp.Domain = $Domain }
        $xml = Get-GPOReport @rp
        $idx = $xml.IndexOf($Text, [System.StringComparison]::OrdinalIgnoreCase)
        if ($idx -ge 0) {
            $start = [math]::Max(0, $idx - 80)
            [pscustomobject]@{
                GPO      = $g.DisplayName
                Id       = $g.Id
                Status   = $g.GpoStatus
                Modified = $g.ModificationTime
                Context  = (($xml.Substring($start, [math]::Min(200, $xml.Length - $start))) -replace '\s+', ' ')
            }
        }
    }
}

function Set-GPSvcDebugLogging {
<#
.SYNOPSIS
Turns the detailed Group Policy trace (%windir%\debug\usermode\gpsvc.log) on or off.
.DESCRIPTION
Sets GPSvcDebugLevel = 0x30002 under HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Diagnostics
(the location current Windows versions read). Reproduce the problem, read the log, then turn it off.
.PARAMETER Enable
On. Without it, the setting is removed.
.EXAMPLE
Set-GPSvcDebugLogging -Enable
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([switch]$Enable)
    $key = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Diagnostics'
    $log = "$env:windir\debug\usermode\gpsvc.log"
    if ($Enable) {
        if ($PSCmdlet.ShouldProcess($env:COMPUTERNAME, 'GPSvcDebugLevel = 0x30002')) {
            New-Item -Path $key -Force | Out-Null
            New-ItemProperty -Path $key -Name GPSvcDebugLevel -PropertyType DWord -Value 0x30002 -Force | Out-Null
            New-Item -Path (Split-Path $log -Parent) -ItemType Directory -Force | Out-Null
            [pscustomobject]@{ Computer = $env:COMPUTERNAME; GPSvcLogging = 'On'; Log = $log; Next = 'Run gpupdate /force or reproduce the logon, then read the log. Turn it off afterwards.' }
        }
    }
    else {
        if ($PSCmdlet.ShouldProcess($env:COMPUTERNAME, 'Remove GPSvcDebugLevel')) {
            Remove-ItemProperty -Path $key -Name GPSvcDebugLevel -ErrorAction SilentlyContinue
            [pscustomobject]@{ Computer = $env:COMPUTERNAME; GPSvcLogging = 'Off'; Log = $log; Next = '' }
        }
    }
}

function Find-FlexLmLicenseFile {
<#
.SYNOPSIS
Finds FlexLM license (.lic) files in the usual Rockwell / FlexNet places and shows their SERVER and VENDOR lines (host, host ID, ports), plus the license path variables.
.PARAMETER Path
Extra folders to search.
.EXAMPLE
Find-FlexLmLicenseFile
.NOTES
A client reaches the server through lmgrd (27000-27009 by default) and then the vendor daemon port - give the vendor a fixed port (VENDOR rockwell port=xxxx) to open it in the firewall.
#>
    [CmdletBinding()]
    param([string[]]$Path = @())
    $dirs = @("${env:ProgramFiles(x86)}\Rockwell Software\FactoryTalk Activation", "$env:ProgramFiles\Rockwell Software\FactoryTalk Activation", "${env:ProgramFiles(x86)}\Common Files\Rockwell", "$env:ProgramData\Rockwell", "$env:ProgramFiles\FlexNet", 'C:\flexlm') + $Path
    $vars = @()
    foreach ($n in 'LM_LICENSE_FILE', 'ROCKWELL_LICENSE_FILE') { $x = [Environment]::GetEnvironmentVariable($n, 'Machine'); if ($x) { $vars += "$n=$x" } }
    $reg = Get-ItemProperty 'HKLM:\SOFTWARE\FLEXlm License Manager', 'HKLM:\SOFTWARE\WOW6432Node\FLEXlm License Manager' -ErrorAction SilentlyContinue
    foreach ($r in @($reg)) { foreach ($p in $r.PSObject.Properties | Where-Object { $_.Name -like '*LICENSE_FILE' }) { $vars += "$($p.Name)=$($p.Value)" } }
    foreach ($d in ($dirs | Where-Object { $_ -and (Test-Path -LiteralPath $_) } | Select-Object -Unique)) {
        foreach ($f in @(Get-ChildItem -LiteralPath $d -Filter *.lic -Recurse -File -ErrorAction SilentlyContinue)) {
            $lines = @(Get-Content -LiteralPath $f.FullName -ErrorAction SilentlyContinue)
            [pscustomobject]@{
                File = $f.FullName; Modified = $f.LastWriteTime
                Server = (@($lines | Where-Object { $_ -match '^\s*SERVER\s' }) -join ' | ')
                Vendor = (@($lines | Where-Object { $_ -match '^\s*(VENDOR|DAEMON)\s' }) -join ' | ')
                Features = @($lines | Where-Object { $_ -match '^\s*(FEATURE|INCREMENT)\s' }).Count
                LicenseVariables = ($vars -join '; ')
            }
        }
    }
}

function Get-IgnitionInfo {
<#
.SYNOPSIS
Ignition service state and run-as account, install folder, version, the bundled Java (and keytool) path, and whether the web ports answer.
.EXAMPLE
Get-IgnitionInfo
#>
    [CmdletBinding()]
    param()
    $svc = Get-CimInstance Win32_Service -Filter "Name='Ignition'" -ErrorAction SilentlyContinue
    $dir = $null
    if ($svc -and $svc.PathName -match '^"?(.+?)\\(lib\\)?[^\\]+\.exe') { $dir = $Matches[1] }
    foreach ($c in "$env:ProgramFiles\Inductive Automation\Ignition", 'C:\Ignition') { if (-not $dir -and (Test-Path $c)) { $dir = $c } }
    $ver = ''
    if ($dir) {
        $vf = Get-ChildItem -LiteralPath $dir -Filter 'version*' -File -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($vf) { $ver = (Get-Content -LiteralPath $vf.FullName -TotalCount 3) -join ' ' }
    }
    $keytool = if ($dir) { Get-ChildItem -LiteralPath $dir -Filter keytool.exe -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1 } else { $null }
    $ports = foreach ($p in 8088, 8043, 8060) {
        $t = New-Object System.Net.Sockets.TcpClient
        $ok = $false
        try { $iar = $t.BeginConnect('localhost', $p, $null, $null); $ok = $iar.AsyncWaitHandle.WaitOne(1500) -and $t.Connected } catch { } finally { $t.Close() }
        "$p=$(if ($ok) { 'open' } else { 'closed' })"
    }
    [pscustomobject]@{
        Computer = $env:COMPUTERNAME; Service = $(if ($svc) { "$($svc.State), $($svc.StartMode)" } else { 'not installed' }); RunAs = $(if ($svc) { $svc.StartName } else { '' })
        InstallPath = $dir; Version = $ver; Keytool = $(if ($keytool) { $keytool.FullName } else { '' })
        CaCerts = $(if ($keytool) { Join-Path (Split-Path (Split-Path $keytool.FullName -Parent) -Parent) 'lib\security\cacerts' } else { '' })
        Ports = ($ports -join ', ')
    }
}

function Get-IgnitionLog {
<#
.SYNOPSIS
Finds the Ignition install, then shows the last lines of logs\wrapper.log, or only the lines matching a pattern.
.PARAMETER Lines
How many lines from the end to read.
.PARAMETER Pattern
Only lines matching this, e.g. "PKIX|LDAP|ERROR".
.PARAMETER InstallPath
Ignition folder if it is not in the usual place.
.EXAMPLE
Get-IgnitionLog -Pattern 'PKIX|SSLHandshake|LDAP' -Lines 2000
#>
    [CmdletBinding()]
    param([int]$Lines = 100, [string]$Pattern, [string]$InstallPath)
    if (-not $InstallPath) {
        $svc = Get-CimInstance Win32_Service -Filter "Name='Ignition'" -ErrorAction SilentlyContinue
        if ($svc -and $svc.PathName -match '^"?(.+?)\\(lib\\)?[^\\]+\.exe') { $InstallPath = $Matches[1] }
        foreach ($c in "$env:ProgramFiles\Inductive Automation\Ignition", "${env:ProgramFiles(x86)}\Inductive Automation\Ignition", 'C:\Ignition') { if (-not $InstallPath -and (Test-Path $c)) { $InstallPath = $c } }
    }
    $log = Join-Path $InstallPath 'logs\wrapper.log'
    if (-not (Test-Path -LiteralPath $log)) { throw "wrapper.log not found under '$InstallPath'. Give -InstallPath." }
    $text = Get-Content -LiteralPath $log -Tail $Lines
    if ($Pattern) { $text = $text | Where-Object { $_ -match $Pattern } }
    $text
}

function Find-DuplicateJsonKey {
<#
.SYNOPSIS
Reads a JSON file and reports any key that appears twice in the same object (most parsers silently keep the last one), with line numbers.
.PARAMETER Path
JSON file(s), one per line.
.EXAMPLE
Find-DuplicateJsonKey -Path "$env:USERPROFILE\.ignition\clientlauncher-data\vision-client-launcher.json"
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string[]]$Path)
    foreach ($f in $Path) {
        $t = [IO.File]::ReadAllText((Resolve-Path -LiteralPath $f).ProviderPath)
        $stack = New-Object System.Collections.Generic.List[object]
        $line = 1; $i = 0; $expectKey = $false; $found = 0
        while ($i -lt $t.Length) {
            $ch = $t[$i]
            if ($ch -eq "`n") { $line++ }
            if ($ch -eq '{' -or $ch -eq '[') {
                $parentPath = '$'
                if ($stack.Count) { $top = $stack[$stack.Count - 1]; $parentPath = $(if ($top.Type -eq 'a') { "$($top.Path)[]" } else { $top.Last }) }
                if ($ch -eq '{') { $stack.Add(@{ Type = 'o'; Keys = @{}; Path = $parentPath; Last = $parentPath }); $expectKey = $true }
                else { $stack.Add(@{ Type = 'a'; Keys = $null; Path = $parentPath; Last = $parentPath }); $expectKey = $false }
            }
            elseif ($ch -eq '}' -or $ch -eq ']') { if ($stack.Count) { $stack.RemoveAt($stack.Count - 1) } }
            elseif ($ch -eq ',') { $expectKey = ($stack.Count -and $stack[$stack.Count - 1].Type -eq 'o') }
            elseif ($ch -eq '"') {
                $j = $i + 1; $sb = New-Object Text.StringBuilder
                while ($j -lt $t.Length -and $t[$j] -ne '"') { if ($t[$j] -eq '\') { [void]$sb.Append($t[$j]); $j++ }; [void]$sb.Append($t[$j]); $j++ }
                $s = $sb.ToString()
                if ($expectKey -and $stack.Count) {
                    $o = $stack[$stack.Count - 1]
                    $o.Last = "$($o.Path).$s"
                    if ($o.Keys.ContainsKey($s)) { $found++; [pscustomobject]@{ File = $f; Key = $s; Object = $o.Path; FirstLine = $o.Keys[$s]; DuplicateLine = $line } }
                    else { $o.Keys[$s] = $line }
                    $expectKey = $false
                }
                $i = $j
            }
            $i++
        }
        if (-not $found) { [pscustomobject]@{ File = $f; Key = '(no duplicates)'; Object = ''; FirstLine = $null; DuplicateLine = $null } }
    }
}

function Set-VisionClientLauncherConfig {
<#
.SYNOPSIS
Sets a top-level setting in vision-client-launcher.json for every user profile (backs each file up first), and reports duplicate keys it removes.
.PARAMETER Setting
JSON property name to set.
.PARAMETER Value
New value. true/false and numbers are written as JSON booleans/numbers.
.PARAMETER FileName
Launcher config file name (designer-launcher.json for the Designer Launcher).
.EXAMPLE
Set-VisionClientLauncherConfig -Setting 'signature.verification.enabled' -Value false -WhatIf
.NOTES
Close the launcher first (Stop-ProcessGracefully -Name javaw). Rewriting with ConvertTo-Json also drops duplicate keys (the last one wins).
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)] [string]$Setting, [Parameter(Mandatory)] [string]$Value, [string]$FileName = 'vision-client-launcher.json')
    $v = if ($Value -eq 'true') { $true } elseif ($Value -eq 'false') { $false } elseif ($Value -match '^-?\d+(\.\d+)?$') { [double]$Value } else { $Value }
    $files = @(Get-ChildItem 'C:\Users\*\.ignition\clientlauncher-data' -Filter $FileName -File -ErrorAction SilentlyContinue)
    $files += @(Get-ChildItem 'C:\Users\*\AppData\Roaming\Inductive Automation\*' -Filter $FileName -Recurse -File -ErrorAction SilentlyContinue)
    if (-not $files.Count) { return [pscustomobject]@{ File = "(no $FileName found in any profile)"; Old = ''; New = ''; Result = '' } }
    foreach ($f in $files) {
        try {
            $j = Get-Content -LiteralPath $f.FullName -Raw | ConvertFrom-Json
            $old = $j.$Setting
            if ($PSCmdlet.ShouldProcess($f.FullName, "$Setting = $Value")) {
                Copy-Item -LiteralPath $f.FullName -Destination "$($f.FullName).$(Get-Date -Format yyyyMMdd_HHmmss).bak"
                if ($j.PSObject.Properties[$Setting]) { $j.$Setting = $v } else { $j | Add-Member -NotePropertyName $Setting -NotePropertyValue $v }
                [IO.File]::WriteAllText($f.FullName, ($j | ConvertTo-Json -Depth 20), (New-Object Text.UTF8Encoding($false)))
                [pscustomobject]@{ File = $f.FullName; Old = [string]$old; New = [string]$v; Result = 'Updated (backup made)' }
            }
        }
        catch { [pscustomobject]@{ File = $f.FullName; Old = ''; New = ''; Result = "Failed: $($_.Exception.Message)" } }
    }
}

function Get-DomainTimeStatus {
<#
.SYNOPSIS
Each DC's time offset and NTP source as w32tm /monitor sees it, plus this computer's own time source.
.PARAMETER Domain
Domain to check.
.EXAMPLE
Get-DomainTimeStatus -Domain domain2.ads
.NOTES
Kerberos fails beyond 5 minutes of skew. On air-gapped networks the PDC emulator of the forest root should sync to a reliable internal source.
#>
    [CmdletBinding()]
    param([string]$Domain = $env:USERDNSDOMAIN)
    $out = @(w32tm /monitor /domain:$Domain 2>&1 | ForEach-Object { [string]$_ })
    $cur = $null
    foreach ($l in $out) {
        if ($l -match '^(\S+)\[([\d\.:]+)\]') { if ($cur) { [pscustomobject]$cur }; $cur = [ordered]@{ DC = $Matches[1]; Address = $Matches[2]; Offset = ''; RefId = ''; Stratum = '' } }
        elseif ($cur -and $l -match 'NTP:\s*(\S+)') { $cur.Offset = $Matches[1] }
        elseif ($cur -and $l -match 'RefID:\s*(.+)$') { $cur.RefId = $Matches[1].Trim() }
        elseif ($cur -and $l -match 'Stratum:\s*(\d+)') { $cur.Stratum = $Matches[1] }
    }
    if ($cur) { [pscustomobject]$cur }
    $src = (@(w32tm /query /source 2>&1) -join ' ').Trim()
    [pscustomobject]@{ DC = "(this computer: $env:COMPUTERNAME)"; Address = ''; Offset = ''; RefId = "Source: $src"; Stratum = '' }
}

function Get-KerberosFailure {
<#
.SYNOPSIS
Failed Kerberos ticket requests from a DC's Security log, with the failure code translated (0x18 = bad password, 0x12 = disabled/locked, 0x25 = clock skew ...).
.PARAMETER UserName
Only this account.
.PARAMETER Hours
How far back.
.PARAMETER MaxEvents
Stop after this many.
.EXAMPLE
Get-KerberosFailure -UserName jsmith -Hours 4
#>
    [CmdletBinding()]
    param([string]$UserName, [int]$Hours = 24, [int]$MaxEvents = 500)
    $codes = @{ '0x6' = 'Unknown user'; '0x7' = 'Unknown service (SPN)'; '0xc' = 'Workstation/time restriction'; '0x12' = 'Account disabled, expired or locked'; '0x17' = 'Password expired'; '0x18' = 'Bad password'; '0x1b' = 'Server requires pre-auth'; '0x1f' = 'Integrity check failed'; '0x20' = 'Ticket expired'; '0x25' = 'Clock skew too great'; '0xe' = 'Encryption type not supported'; '0x29' = 'Message modified' }
    Get-WinEvent -FilterHashtable @{ LogName = 'Security'; Id = 4768, 4769, 4771; StartTime = (Get-Date).AddHours(-$Hours) } -MaxEvents $MaxEvents -ErrorAction SilentlyContinue |
        ForEach-Object {
            $x = [xml]$_.ToXml()
            $d = @{}
            foreach ($n in $x.Event.EventData.Data) { $d[$n.Name] = $n.'#text' }
            $st = [string]$d['Status']
            if (-not $st -or $st -eq '0x0') { return }
            $user = [string]$d['TargetUserName']
            if ($UserName -and $user -notlike "$UserName*") { return }
            [pscustomobject]@{
                Time = $_.TimeCreated; EventId = $_.Id; User = $user; Service = $d['ServiceName']
                Client = ([string]$d['IpAddress'] -replace '^::ffff:', ''); Code = $st
                Meaning = $(if ($codes.ContainsKey($st.ToLower())) { $codes[$st.ToLower()] } else { '' })
            }
        }
}

function Set-KerberosLogging {
<#
.SYNOPSIS
Turns Kerberos error logging to the System event log on or off (HKLM\SYSTEM\CurrentControlSet\Control\Lsa\Kerberos\Parameters LogLevel = 1).
.PARAMETER Enable
On. Without it, the setting is removed.
.EXAMPLE
Set-KerberosLogging -Enable
.NOTES
Turn it off afterwards - it is noisy. Errors show as source "Kerberos" in the System log (Search-EventLogText -Text Kerberos).
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([switch]$Enable)
    $key = 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa\Kerberos\Parameters'
    if ($Enable) {
        if ($PSCmdlet.ShouldProcess($env:COMPUTERNAME, 'Kerberos LogLevel = 1')) {
            if (-not (Test-Path $key)) { New-Item -Path $key -Force | Out-Null }
            New-ItemProperty -Path $key -Name LogLevel -PropertyType DWord -Value 1 -Force | Out-Null
            [pscustomobject]@{ Computer = $env:COMPUTERNAME; KerberosLogging = 'On'; Note = 'Takes effect immediately. Errors go to the System log.' }
        }
    }
    elseif ($PSCmdlet.ShouldProcess($env:COMPUTERNAME, 'Remove Kerberos LogLevel')) {
        Remove-ItemProperty -Path $key -Name LogLevel -ErrorAction SilentlyContinue
        [pscustomobject]@{ Computer = $env:COMPUTERNAME; KerberosLogging = 'Off'; Note = '' }
    }
}

function Get-KerberosTicket {
<#
.SYNOPSIS
The cached Kerberos tickets (klist) as a table: server, encryption, start and end time, and the KDC that issued them.
.PARAMETER Computer
The computer account's tickets (LogonId 0x3e7) instead of yours.
.PARAMETER Purge
Delete the tickets first, so the next access gets fresh ones (and new group memberships).
.EXAMPLE
Get-KerberosTicket -Computer
#>
    [CmdletBinding()]
    param([switch]$Computer, [switch]$Purge)
    $li = if ($Computer) { @('-li', '0x3e7') } else { @() }
    if ($Purge) { klist @li purge | Out-Null }
    $out = @(klist @li 2>&1 | ForEach-Object { [string]$_ })
    $t = $null
    foreach ($l in $out) {
        if ($l -match '^#\d+>\s*Client:\s*(.+)$') { if ($t) { [pscustomobject]$t }; $t = [ordered]@{ Client = $Matches[1].Trim(); Server = ''; Encryption = ''; Start = ''; End = ''; Renew = ''; Kdc = '' } }
        elseif ($t -and $l -match '^\s*Server:\s*(.+)$') { $t.Server = $Matches[1].Trim() }
        elseif ($t -and $l -match 'KerbTicket Encryption Type:\s*(.+)$') { $t.Encryption = $Matches[1].Trim() }
        elseif ($t -and $l -match 'Start Time:\s*(.+?)\s*\(') { $t.Start = $Matches[1] }
        elseif ($t -and $l -match 'End Time:\s*(.+?)\s*\(') { $t.End = $Matches[1] }
        elseif ($t -and $l -match 'Renew Time:\s*(.+?)\s*\(') { $t.Renew = $Matches[1] }
        elseif ($t -and $l -match 'Kdc Called:\s*(.*)$') { $t.Kdc = $Matches[1].Trim() }
    }
    if ($t) { [pscustomobject]$t }
}

function Get-NetworkAdapterInfo {
<#
.SYNOPSIS
Each connected adapter's MAC address, IPv4 address, prefix, subnet broadcast address, gateway and DNS servers - what you need to build a Wake-on-LAN list.
.PARAMETER IncludeDisconnected
Also list adapters that are not connected.
.EXAMPLE
Get-NetworkAdapterInfo
#>
    [CmdletBinding()]
    param([switch]$IncludeDisconnected)
    foreach ($cfg in @(Get-CimInstance Win32_NetworkAdapterConfiguration -Filter 'MACAddress IS NOT NULL' -ErrorAction SilentlyContinue)) {
        $ips = @($cfg.IPAddress | Where-Object { $_ -match '^\d+\.\d+\.\d+\.\d+$' })
        if (-not $IncludeDisconnected -and -not $cfg.IPEnabled) { continue }
        $i = 0
        foreach ($ip in $(if ($ips.Count) { $ips } else { @('') })) {
            $mask = if ($ip) { @($cfg.IPSubnet)[$i] } else { '' }
            $bcast = ''
            if ($ip -and $mask -match '^\d+\.\d+\.\d+\.\d+$') {
                $a = ([System.Net.IPAddress]::Parse($ip)).GetAddressBytes(); $m = ([System.Net.IPAddress]::Parse($mask)).GetAddressBytes()
                $b = for ($k = 0; $k -lt 4; $k++) { ($a[$k] -band $m[$k]) -bor (255 -bxor $m[$k]) }
                $bcast = $b -join '.'
            }
            [pscustomobject]@{
                Computer = $env:COMPUTERNAME; Adapter = $cfg.Description; MAC = $cfg.MACAddress; IPAddress = $ip; SubnetMask = $mask; Broadcast = $bcast
                Gateway = (@($cfg.DefaultIPGateway) -join ', '); DNS = (@($cfg.DNSServerSearchOrder) -join ', '); DHCP = $cfg.DHCPEnabled
            }
            $i++
        }
    }
}

function Get-FirewallRuleStatus {
<#
.SYNOPSIS
Windows Firewall rules whose display name matches, with enabled state, direction, action and ports.
.PARAMETER DisplayName
Wildcard on the rule name, e.g. *Active Directory Web Services* or *Remote Desktop*.
.PARAMETER Port
Or: rules that cover this local port.
.EXAMPLE
Get-FirewallRuleStatus -DisplayName '*Active Directory Web Services*'
#>
    [CmdletBinding()]
    param([string]$DisplayName = '*', [int]$Port = 0)
    $rules = @(Get-NetFirewallRule -DisplayName $DisplayName -ErrorAction SilentlyContinue)
    foreach ($r in $rules) {
        $pf = $r | Get-NetFirewallPortFilter -ErrorAction SilentlyContinue
        if ($Port -gt 0 -and -not (@($pf.LocalPort) -contains [string]$Port)) { continue }
