    }
}

function Test-HostPing {
<#
.SYNOPSIS
Pings each host a few times and shows the resolved address, replies and average time.
.PARAMETER ComputerName
Hosts, one per line.
.PARAMETER Count
Pings per host.
.EXAMPLE
Test-HostPing -ComputerName server01, 10.1.2.3
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string[]]$ComputerName, [int]$Count = 4)
    $ping = New-Object System.Net.NetworkInformation.Ping
    foreach ($c in $ComputerName) {
        $ok = 0; $times = @(); $addr = ''
        for ($i = 0; $i -lt $Count; $i++) {
            try { $r = $ping.Send($c, 1500); if ($r.Status -eq 'Success') { $ok++; $times += $r.RoundtripTime; $addr = [string]$r.Address } } catch { $addr = $_.Exception.InnerException.Message }
        }
        [pscustomobject]@{ Host = $c; Address = $addr; Replies = "$ok/$Count"; AvgMs = $(if ($times.Count) { [math]::Round(($times | Measure-Object -Average).Average, 1) } else { $null }) }
    }
    $ping.Dispose()
}

function Get-ListeningPort {
<#
.SYNOPSIS
Which processes are listening on a port or port range on this computer.
.PARAMETER Port
Ports, one per line, or a range like 27000-27009. Empty = everything listening.
.EXAMPLE
Get-ListeningPort -Port 27000-27009
.EXAMPLE
Get-ListeningPort -Port 9389, 636, 389
#>
    [CmdletBinding()]
    param([string[]]$Port = @())
    $want = @()
    foreach ($p in $Port) {
        foreach ($part in ($p -split '[,;\s]+' | Where-Object { $_ })) {
            if ($part -match '^(\d+)-(\d+)$') { $want += [int]$Matches[1]..[int]$Matches[2] } else { $want += [int]$part }
        }
    }
    $listen = @(Get-NetTCPConnection -State Listen -ErrorAction Stop)
    if ($want.Count) { $listen = @($listen | Where-Object { $want -contains $_.LocalPort }) }
    $procs = @{}
    foreach ($l in $listen | Sort-Object LocalPort) {
        if (-not $procs.ContainsKey($l.OwningProcess)) { $procs[$l.OwningProcess] = Get-Process -Id $l.OwningProcess -ErrorAction SilentlyContinue }
        $pr = $procs[$l.OwningProcess]
        [pscustomobject]@{ Port = $l.LocalPort; Address = $l.LocalAddress; Process = $(if ($pr) { $pr.ProcessName } else { '' }); PID = $l.OwningProcess; Path = $(if ($pr) { $pr.Path } else { '' }) }
    }
    if ($want.Count -and $listen.Count -eq 0) { Write-Warning "Nothing is listening on $($Port -join ', ')." }
}

