function Test-TcpPort {
<#
.SYNOPSIS
Fast TCP connect test to one or more hosts and ports, with a short timeout (much quicker than Test-NetConnection on closed ports).
.PARAMETER ComputerName
Hosts, one per line.
.PARAMETER Port
Ports, one per line.
.PARAMETER TimeoutMs
How long to wait per port.
.EXAMPLE
Test-TcpPort -ComputerName sccm01, dp01 -Port 80, 443, 8530
.NOTES
"Timed out" = a firewall silently dropping (Winsock 10060). "Refused" = host reachable, nothing listening (10061).
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string[]]$ComputerName, [Parameter(Mandatory)] [int[]]$Port, [int]$TimeoutMs = 2000)
    foreach ($c in $ComputerName) {
        foreach ($p in $Port) {
            $t = New-Object System.Net.Sockets.TcpClient
            $sw = [Diagnostics.Stopwatch]::StartNew()
            $res = 'Timed out'
            try {
                $iar = $t.BeginConnect($c, $p, $null, $null)
                if ($iar.AsyncWaitHandle.WaitOne($TimeoutMs)) { try { $t.EndConnect($iar); $res = 'Open' } catch { $res = $(if ($_.Exception.InnerException -and $_.Exception.InnerException.Message -match 'refused|actively') { 'Refused' } else { $_.Exception.InnerException.Message }) } }
            }
            catch { $res = $_.Exception.Message }
            finally { $t.Close() }
            [pscustomobject]@{ Host = $c; Port = $p; Result = $res; Ms = $sw.ElapsedMilliseconds; From = $env:COMPUTERNAME }
        }
    }
}

function Get-SubnetInfo {
<#
.SYNOPSIS
Network address, broadcast address, mask, first/last usable address and host count for an IP with a prefix (CIDR).
.PARAMETER Address
IP/prefix, e.g. 10.208.45.50/24 - one per line.
.EXAMPLE
Get-SubnetInfo -Address 10.208.45.50/24, 192.168.1.10/26
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string[]]$Address)
    foreach ($a in $Address) {
        if ($a -notmatch '^(\d+\.\d+\.\d+\.\d+)/(\d{1,2})$') { Write-Error "Not IP/prefix: $a"; continue }
        $ip = $Matches[1]; $len = [int]$Matches[2]
        $b = ([System.Net.IPAddress]::Parse($ip)).GetAddressBytes(); [Array]::Reverse($b)
        $n = [BitConverter]::ToUInt32($b, 0)
        $mask = if ($len -eq 0) { [uint32]0 } else { [uint32]([math]::Pow(2, 32) - [math]::Pow(2, 32 - $len)) }
        $net = $n -band $mask
        $bc = $net -bor ([uint32]::MaxValue -bxor $mask)
        $toIp = { param($v) $x = [BitConverter]::GetBytes([uint32]$v); [Array]::Reverse($x); ([System.Net.IPAddress]$x).ToString() }
        [pscustomobject]@{
            Input = $a; Network = (& $toIp $net); Broadcast = (& $toIp $bc); Mask = (& $toIp $mask)
            FirstHost = $(if ($len -lt 31) { & $toIp ($net + 1) } else { & $toIp $net }); LastHost = $(if ($len -lt 31) { & $toIp ($bc - 1) } else { & $toIp $bc })
            Hosts = $(if ($len -ge 31) { [math]::Pow(2, 32 - $len) } else { [math]::Pow(2, 32 - $len) - 2 })
        }
    }
}

function Get-TraceRoute {
<#
.SYNOPSIS
Runs tracert without name lookups and returns one row per hop.
.PARAMETER ComputerName
Destination.
.PARAMETER MaxHops
Maximum hops.
.EXAMPLE
Get-TraceRoute -ComputerName dc1.domain2.ads
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string]$ComputerName, [int]$MaxHops = 20)
    foreach ($l in @(tracert -d -h $MaxHops -w 1000 $ComputerName 2>&1 | ForEach-Object { [string]$_ })) {
        if ($l -match '^\s*(\d+)\s+(.+?)\s+(\d+\.\d+\.\d+\.\d+|Request timed out\.)\s*$') {
            $ms = @([regex]::Matches($Matches[2], '(<?\d+) ms') | ForEach-Object { $_.Groups[1].Value })
            [pscustomobject]@{ Hop = [int]$Matches[1]; Address = $Matches[3]; Times = ($ms -join ', '); TimedOut = ($Matches[3] -like 'Request*') }
        }
    }
}

function Wait-HostReachable {
<#
.SYNOPSIS
Waits until a host answers ping (or a TCP port), up to a timeout - e.g. after a reboot, or before a step that needs the network.
.PARAMETER ComputerName
Host to wait for.
.PARAMETER Port
Wait for this TCP port instead of ping (use it when ICMP is blocked).
.PARAMETER TimeoutSeconds
Give up after this long.
.EXAMPLE
Wait-HostReachable -ComputerName server01 -Port 3389 -TimeoutSeconds 600
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string]$ComputerName, [int]$Port = 0, [int]$TimeoutSeconds = 120)
    $sw = [Diagnostics.Stopwatch]::StartNew()
    $tries = 0
    while ($sw.Elapsed.TotalSeconds -lt $TimeoutSeconds) {
        $tries++
        $ok = $false
        if ($Port -gt 0) {
            $t = New-Object System.Net.Sockets.TcpClient
            try { $iar = $t.BeginConnect($ComputerName, $Port, $null, $null); $ok = $iar.AsyncWaitHandle.WaitOne(2000) -and $t.Connected } catch { } finally { $t.Close() }
        }
        else {
            try { $ok = (New-Object System.Net.NetworkInformation.Ping).Send($ComputerName, 1500).Status -eq 'Success' } catch { }
        }
        if ($ok) { return [pscustomobject]@{ Host = $ComputerName; Reachable = $true; Seconds = [math]::Round($sw.Elapsed.TotalSeconds, 1); Tries = $tries } }
        Start-Sleep -Seconds 2
    }
    [pscustomobject]@{ Host = $ComputerName; Reachable = $false; Seconds = [math]::Round($sw.Elapsed.TotalSeconds, 1); Tries = $tries }
}

