function Resolve-Sid {
<#
.SYNOPSIS
Turns SIDs into account names, or account names into SIDs (e.g. the *S-1-5-... entries in a user-rights export).
.PARAMETER Value
SIDs or account names, one per line (a leading * is ignored).
.EXAMPLE
Resolve-Sid -Value 'S-1-5-32-544','*S-1-5-21-1684435202-2345963373-158578869-512','CONTOSO\Domain Admins'
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string[]]$Value)
    foreach ($v in $Value) {
        $s = $v.Trim().TrimStart('*')
        if (-not $s) { continue }
        if ($s -match '^S-\d-') {
            $name = ''
            try { $name = (New-Object System.Security.Principal.SecurityIdentifier($s)).Translate([System.Security.Principal.NTAccount]).Value } catch { $name = '(unresolved - account may be deleted)' }
            [pscustomobject]@{ Input = $v; SID = $s; Name = $name }
        }
        else {
            $sid = ''
            try { $sid = (New-Object System.Security.Principal.NTAccount($s)).Translate([System.Security.Principal.SecurityIdentifier]).Value } catch { $sid = '(not found)' }
            [pscustomobject]@{ Input = $v; SID = $sid; Name = $s }
        }
    }
}

function Get-UserRightsAssignment {
<#
.SYNOPSIS
Who holds each user right on this computer (log on as a batch job, as a service, deny ...).
.DESCRIPTION
Exports the local security policy with secedit and translates the SIDs to names.
.PARAMETER Right
Wildcard on the right's name, e.g. *Batch* or *Deny*. Default lists the logon rights.
.EXAMPLE
Get-UserRightsAssignment -Right '*Batch*'
.NOTES
Needs an elevated session. The export goes to a temp file that is deleted afterwards.
#>
    [CmdletBinding()]
    param([string]$Right = 'Se*Logon*')
    $tmp = Join-Path $env:TEMP ("rights_{0}.inf" -f [guid]::NewGuid())
    try {
        secedit /export /cfg $tmp /areas USER_RIGHTS | Out-Null
        foreach ($line in (Get-Content -LiteralPath $tmp)) {
            if ($line -notmatch '^(Se\w+)\s*=\s*(.*)$') { continue }
            $name = $Matches[1]; $list = $Matches[2]
            if ($name -notlike $Right) { continue }
            $accounts = foreach ($a in ($list -split ',')) {
                $a = $a.Trim()
                if ($a -like '*S-*') {
                    $sid = $a.TrimStart('*')
                    try { (New-Object System.Security.Principal.SecurityIdentifier($sid)).Translate([System.Security.Principal.NTAccount]).Value } catch { $sid }
                }
                elseif ($a) { $a }
            }
            [pscustomobject]@{ Right = $name; Accounts = ($accounts -join '; ') }
        }
    }
    finally { Remove-Item -LiteralPath $tmp -ErrorAction SilentlyContinue }
}

function Get-PSEnvironmentInfo {
<#
.SYNOPSIS
What this computer can run: OS, PowerShell and .NET versions, remoting, RSAT / AD / GPMC / LAPS modules.
.EXAMPLE
Get-PSEnvironmentInfo
#>
    [CmdletBinding()]
    param()
    $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
    $rel = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\NET Framework Setup\NDP\v4\Full' -ErrorAction SilentlyContinue).Release
    $net = switch ($true) {
        ($rel -ge 533320) { '4.8.1'; break } ($rel -ge 528040) { '4.8'; break } ($rel -ge 461808) { '4.7.2'; break }
        ($rel -ge 460798) { '4.7'; break } ($rel -ge 394802) { '4.6.2'; break } ($rel -ge 379893) { '4.5.2'; break }
        default { if ($rel) { "release $rel" } else { 'not found' } }
    }
    $mods = @{}
    foreach ($m in 'ActiveDirectory', 'GroupPolicy', 'DnsServer', 'LAPS', 'AdmPwd.PS', 'ScheduledTasks', 'ServerManager') {
        $mods[$m] = [bool](Get-Module -ListAvailable -Name $m -ErrorAction SilentlyContinue)
    }
    $winrm = Get-Service WinRM -ErrorAction SilentlyContinue
    [pscustomobject]@{
        Computer       = $env:COMPUTERNAME
        OS             = $os.Caption
