function Stop-ProcessGracefully {
<#
.SYNOPSIS
Asks a program to close (like clicking X), waits, then kills what is left - e.g. before installing an update.
.PARAMETER Name
Process names, one per line, without .exe (e.g. javaw, chrome, firefox).
.PARAMETER WaitSeconds
How long to wait for a nice close before forcing.
.PARAMETER Force
Skip the nice close and kill straight away (like taskkill /F).
.EXAMPLE
Stop-ProcessGracefully -Name javaw
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)] [string[]]$Name, [int]$WaitSeconds = 5, [switch]$Force)
    foreach ($n in $Name) {
        $procs = @(Get-Process -Name ($n -replace '\.exe$', '') -ErrorAction SilentlyContinue)
        if ($procs.Count -eq 0) { [pscustomobject]@{ Process = $n; PID = $null; Result = 'Not running' }; continue }
        foreach ($p in $procs) {
            if (-not $PSCmdlet.ShouldProcess("$($p.ProcessName) ($($p.Id))", 'Stop')) { continue }
            $result = 'Closed'
            if (-not $Force) {
                try { [void]$p.CloseMainWindow() } catch { }
                if (-not $p.WaitForExit($WaitSeconds * 1000)) { Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue; $result = 'Killed after wait' }
            }
            else { Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue; $result = 'Killed' }
            [pscustomobject]@{ Process = $p.ProcessName; PID = $p.Id; Result = $result }
        }
    }
}

function Restart-ServiceClean {
<#
.SYNOPSIS
Stops a service, waits for its process to really exit (kills it after a timeout), then starts it again.
.DESCRIPTION
For services whose process hangs and stays alive after "stop" (e.g. a license daemon), so a
normal restart does not clear the bad state.
.PARAMETER Name
Service name.
.PARAMETER TimeoutSeconds
How long to wait for a clean stop before killing the process.
.EXAMPLE
Restart-ServiceClean -Name WDSServer
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)] [string]$Name, [int]$TimeoutSeconds = 30)
    $svc = Get-CimInstance Win32_Service -Filter ("Name='" + ($Name -replace "'", "''") + "'") -ErrorAction Stop
    if (-not $svc) { throw "Service not found: $Name" }
    if (-not $PSCmdlet.ShouldProcess($Name, 'Stop, wait, start')) { return }
    $procId = [int]$svc.ProcessId
    Stop-Service -Name $Name -Force -ErrorAction SilentlyContinue
    $sw = [Diagnostics.Stopwatch]::StartNew()
    while ($procId -gt 0 -and (Get-Process -Id $procId -ErrorAction SilentlyContinue) -and $sw.Elapsed.TotalSeconds -lt $TimeoutSeconds) { Start-Sleep -Milliseconds 500 }
    $killed = $false
    if ($procId -gt 0 -and (Get-Process -Id $procId -ErrorAction SilentlyContinue)) {
        $shared = @(Get-CimInstance Win32_Service -Filter "ProcessId = $procId" | Where-Object { $_.State -eq 'Running' }).Count
        if ($shared -le 0) { Stop-Process -Id $procId -Force -ErrorAction SilentlyContinue; $killed = $true }
        else { Write-Warning "Process $procId also hosts other running services - not killed." }
    }
    Start-Service -Name $Name -ErrorAction Stop
    $after = Get-Service -Name $Name
    [pscustomobject]@{ Service = $Name; OldPID = $procId; Killed = $killed; Status = [string]$after.Status; Seconds = [math]::Round($sw.Elapsed.TotalSeconds, 1) }
}

