function Start-ServiceWithStartup {
<#
.SYNOPSIS
Sets a service's startup type (Automatic, Manual, Disabled) and starts it, then shows the result and any start failure event.
.PARAMETER Name
Service name(s), one per line.
.PARAMETER StartupType
New startup type.
.EXAMPLE
Start-ServiceWithStartup -Name ADWS -StartupType Automatic
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)] [string[]]$Name, [ValidateSet('Automatic', 'Manual', 'Disabled')] [string]$StartupType = 'Automatic')
    foreach ($n in $Name) {
        $err = ''
        if ($PSCmdlet.ShouldProcess($n, "Startup $StartupType and start")) {
            try {
                Set-Service -Name $n -StartupType $StartupType -ErrorAction Stop
                if ($StartupType -ne 'Disabled') { Start-Service -Name $n -ErrorAction Stop }
            }
            catch { $err = $_.Exception.Message }
        }
        $s = Get-CimInstance Win32_Service -Filter "Name='$n'"
        [pscustomobject]@{ Service = $n; State = $s.State; StartMode = $s.StartMode; RunAs = $s.StartName; Error = $err }
    }
}

function Get-StoppedAutoService {
<#
.SYNOPSIS
Services set to start automatically that are currently stopped (usually crashed or failed at boot).
.PARAMETER IncludeTriggerStart
Also list "Automatic (Trigger Start)" services, which are often stopped on purpose.
.EXAMPLE
Get-StoppedAutoService
.NOTES
Look up why with Get-ServiceFailureEvent -Name <service>.
#>
    [CmdletBinding()]
    param([switch]$IncludeTriggerStart)
    $trigger = @{}
    if (-not $IncludeTriggerStart) {
        foreach ($k in @(Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Services' -ErrorAction SilentlyContinue)) {
            if (Test-Path (Join-Path $k.PSPath 'TriggerInfo')) { $trigger[$k.PSChildName.ToLower()] = $true }
        }
    }
    Get-CimInstance Win32_Service -Filter "StartMode='Auto' AND State<>'Running'" |
        Where-Object { $IncludeTriggerStart -or -not $trigger.ContainsKey($_.Name.ToLower()) } |
        Sort-Object DisplayName |
        Select-Object @{ N = 'Computer'; E = { $env:COMPUTERNAME } }, Name, DisplayName, State, ExitCode, StartName, PathName
}

function Get-PxeServiceStatus {
<#
.SYNOPSIS
State of the SccmPxe and WDSServer services, the newest SMSPXE.log, and recent WDS / service-crash events.
.PARAMETER Hours
How far back for events.
.EXAMPLE
Get-PxeServiceStatus
.NOTES
Restart with Restart-ServiceClean -Name SccmPxe (or WDSServer). After changing boot images, the DP must redistribute them.
#>
    [CmdletBinding()]
    param([int]$Hours = 24)
    foreach ($s in @(Get-CimInstance Win32_Service -Filter "Name='SccmPxe' OR Name='WDSServer'" -ErrorAction SilentlyContinue)) {
        [pscustomobject]@{ Kind = 'Service'; Time = $null; Name = $s.Name; Detail = "$($s.State), $($s.StartMode), $($s.StartName)" }
    }
    $logs = @("$env:windir\System32\SMSPXE\SMSPXE.log", "$env:ProgramFiles\SMS_CCM\Logs\SMSPXE.log", 'C:\SMS_DP$\sms\logs\SMSPXE.log') | Where-Object { Test-Path $_ }
    foreach ($l in $logs) { $i = Get-Item $l; [pscustomobject]@{ Kind = 'Log'; Time = $i.LastWriteTime; Name = $l; Detail = "$([math]::Round($i.Length / 1KB)) KB" } }
    $since = (Get-Date).AddHours(-$Hours)
    Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Service Control Manager'; Id = 7000, 7001, 7009, 7011, 7023, 7024, 7031, 7034; StartTime = $since } -ErrorAction SilentlyContinue |
        Where-Object { $_.Message -match 'PXE|Deployment Services|WDS' } |
        ForEach-Object { [pscustomobject]@{ Kind = 'Event'; Time = $_.TimeCreated; Name = "System $($_.Id)"; Detail = ($_.Message -replace '\s+', ' ') } }
    Get-WinEvent -FilterHashtable @{ LogName = 'Application'; ProviderName = 'WDSServer', 'WDSPXE', 'WDSIMGSRV'; StartTime = $since; Level = 1, 2, 3 } -ErrorAction SilentlyContinue |
        ForEach-Object { [pscustomobject]@{ Kind = 'Event'; Time = $_.TimeCreated; Name = "$($_.ProviderName) $($_.Id)"; Detail = ($_.Message -replace '\s+', ' ') } }
}

function Invoke-SccmClientAction {
<#
.SYNOPSIS
Runs Configuration Manager client actions - the same as the buttons on the Actions tab of the Configuration Manager control panel.
.PARAMETER Action
Which actions.
.EXAMPLE
Invoke-SccmClientAction -Action MachinePolicy, AppDeploymentEval
.NOTES
Results show in PolicyAgent.log, AppDiscovery.log and UpdatesDeployment.log (Find-SccmLog).
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([ValidateSet('MachinePolicy', 'UserPolicy', 'AppDeploymentEval', 'SoftwareUpdatesScan', 'SoftwareUpdatesEval', 'HardwareInventory', 'SoftwareInventory', 'DiscoveryData')] [string[]]$Action = @('MachinePolicy', 'AppDeploymentEval'))
    $ids = @{
        MachinePolicy = '{00000000-0000-0000-0000-000000000021}'; UserPolicy = '{00000000-0000-0000-0000-000000000027}'
        AppDeploymentEval = '{00000000-0000-0000-0000-000000000121}'; SoftwareUpdatesScan = '{00000000-0000-0000-0000-000000000113}'
        SoftwareUpdatesEval = '{00000000-0000-0000-0000-000000000108}'; HardwareInventory = '{00000000-0000-0000-0000-000000000001}'
        SoftwareInventory = '{00000000-0000-0000-0000-000000000002}'; DiscoveryData = '{00000000-0000-0000-0000-000000000003}'
    }
    foreach ($a in $Action) {
        if (-not $PSCmdlet.ShouldProcess($env:COMPUTERNAME, "SCCM client action $a")) { continue }
        try {
            Invoke-CimMethod -Namespace root\ccm -ClassName SMS_Client -MethodName TriggerSchedule -Arguments @{ sScheduleID = $ids[$a] } -ErrorAction Stop | Out-Null
            [pscustomobject]@{ Computer = $env:COMPUTERNAME; Action = $a; Result = 'Triggered' }
        }
        catch { [pscustomobject]@{ Computer = $env:COMPUTERNAME; Action = $a; Result = $_.Exception.Message } }
    }
}

function Test-SccmManagementPoint {
<#
.SYNOPSIS
Calls the management point's MPLIST and MPCERT URLs over HTTP/HTTPS and shows the status code and the start of the answer.
.PARAMETER Server
Management point name.
.PARAMETER UseHttps
Use HTTPS (enhanced HTTP / PKI sites).
.EXAMPLE
Test-SccmManagementPoint -Server sccm01.contoso.com
.NOTES
200 with XML = the MP is fine and reachable. 403/500 = an IIS or MP role problem (check mpcontrol.log on the server).
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string]$Server, [switch]$UseHttps)
    $scheme = if ($UseHttps) { 'https' } else { 'http' }
    foreach ($q in 'mplist', 'mpcert') {
        $url = "${scheme}://$Server/sms_mp/.sms_aut?$q"
        $sw = [Diagnostics.Stopwatch]::StartNew()
        try {
            $r = Invoke-WebRequest -Uri $url -UseBasicParsing -UseDefaultCredentials -TimeoutSec 20 -ErrorAction Stop
            [pscustomobject]@{ Url = $url; Status = [int]$r.StatusCode; Ms = $sw.ElapsedMilliseconds; Answer = ([string]$r.Content).Substring(0, [math]::Min(200, ([string]$r.Content).Length)) }
        }
        catch {
            $code = $null
            if ($_.Exception.Response) { $code = [int]$_.Exception.Response.StatusCode }
            [pscustomobject]@{ Url = $url; Status = $code; Ms = $sw.ElapsedMilliseconds; Answer = $_.Exception.Message }
        }
    }
}

function Set-WdsTracing {
<#
.SYNOPSIS
Turns WDS server tracing on or off (HKLM\SOFTWARE\Microsoft\Tracing\WDSServer EnableFileTracing). The trace is written to %windir%\tracing\wdsserver.log.
.PARAMETER Enable
On. Without it, tracing is turned off.
.EXAMPLE
Set-WdsTracing -Enable
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([switch]$Enable)
    $key = 'HKLM:\SOFTWARE\Microsoft\Tracing\WDSServer'
    if ($PSCmdlet.ShouldProcess($env:COMPUTERNAME, "WDS EnableFileTracing = $([int][bool]$Enable)")) {
        if (-not (Test-Path $key)) { New-Item -Path $key -Force | Out-Null }
        New-ItemProperty -Path $key -Name EnableFileTracing -PropertyType DWord -Value ([int][bool]$Enable) -Force | Out-Null
    }
    [pscustomobject]@{ Computer = $env:COMPUTERNAME; Tracing = $(if ($Enable) { 'On' } else { 'Off' }); Log = "$env:windir\tracing\wdsserver.log"; Note = 'Restart WDSServer for it to take effect.' }
}

