function Get-ScheduledTaskStatus {
<#
.SYNOPSIS
Scheduled tasks with state, run-as account, last run time, last result (translated) and next run time.
.PARAMETER Name
Task name filter (wildcards). Empty = all tasks outside \Microsoft\.
.PARAMETER IncludeMicrosoft
Also list the built-in \Microsoft\ tasks.
.EXAMPLE
Get-ScheduledTaskStatus -Name '*Backup*'
#>
    [CmdletBinding()]
    param([string]$Name = '*', [switch]$IncludeMicrosoft)
    $known = @{ 0 = 'Success'; 1 = 'Incorrect function / script error (exit 1)'; 2 = 'File not found'; 267009 = 'Running'; 267010 = 'Disabled'; 267011 = 'Has not run yet'; 267014 = 'Terminated by user'; 2147750687 = 'Already running'; 2147942402 = 'File not found'; 2147942405 = 'Access denied'; 2147943645 = 'Logon failure / service account password' ; 3221225786 = 'Ended by Ctrl+C / closed' }
    Get-ScheduledTask -TaskName $Name -ErrorAction SilentlyContinue |
        Where-Object { $IncludeMicrosoft -or $_.TaskPath -notlike '\Microsoft\*' } |
        ForEach-Object {
            $i = $_ | Get-ScheduledTaskInfo -ErrorAction SilentlyContinue
            $r = if ($i) { [uint32]$i.LastTaskResult } else { $null }
            [pscustomobject]@{
                Task = "$($_.TaskPath)$($_.TaskName)"; State = [string]$_.State; RunAs = $_.Principal.UserId
                LastRun = $(if ($i) { $i.LastRunTime } else { $null }); LastResult = $(if ($null -ne $r) { '0x{0:X} {1}' -f $r, $(if ($known.ContainsKey([long]$r)) { $known[[long]$r] } else { '' }) } else { '' })
                NextRun = $(if ($i) { $i.NextRunTime } else { $null }); Action = (@($_.Actions) | ForEach-Object { "$($_.Execute) $($_.Arguments)".Trim() }) -join ' ; '
            }
        }
}

function Get-AppPath {
<#
.SYNOPSIS
Finds an application's executable through the App Paths registry keys, the PATH, and Store (Appx) packages.
.PARAMETER Name
Exe or app name, e.g. firefox, chrome, excel.
.EXAMPLE
Get-AppPath -Name firefox
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string]$Name)
    $exe = if ($Name -like '*.exe') { $Name } else { "$Name.exe" }
    foreach ($k in "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\$exe", "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\$exe", "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\App Paths\$exe") {
        $v = Get-ItemProperty -Path $k -ErrorAction SilentlyContinue
        if ($v) { [pscustomobject]@{ Source = ($k -split '\\')[0]; Path = $v.'(default)'.Trim('"'); Version = $(if ($v.'(default)' -and (Test-Path $v.'(default)'.Trim('"'))) { (Get-Item $v.'(default)'.Trim('"')).VersionInfo.ProductVersion } else { '' }) } }
    }
    foreach ($c in @(Get-Command $exe -CommandType Application -ErrorAction SilentlyContinue)) { [pscustomobject]@{ Source = 'PATH'; Path = $c.Source; Version = $c.Version } }
    foreach ($a in @(Get-AppxPackage -Name "*$($Name -replace '\.exe$')*" -ErrorAction SilentlyContinue)) { [pscustomobject]@{ Source = 'Store app'; Path = $a.InstallLocation; Version = [string]$a.Version } }
}

function Test-ChromeInitialPreferences {
<#
.SYNOPSIS
Finds Chrome, checks for initial_preferences / master_preferences next to chrome.exe, validates the JSON and shows the settings in it.
.EXAMPLE
Test-ChromeInitialPreferences
.NOTES
The file only applies to profiles created after it was placed. Existing profiles keep their settings - use policies (HKLM\SOFTWARE\Policies\Google\Chrome) for those.
#>
    [CmdletBinding()]
    param()
    $dirs = @("${env:ProgramFiles}\Google\Chrome\Application", "${env:ProgramFiles(x86)}\Google\Chrome\Application") | Where-Object { $_ -and (Test-Path (Join-Path $_ 'chrome.exe')) }
    if (-not $dirs) { return [pscustomobject]@{ Chrome = 'Not found (machine-wide)'; File = ''; ValidJson = $null; Settings = '' } }
    foreach ($d in $dirs) {
        $ver = (Get-Item (Join-Path $d 'chrome.exe')).VersionInfo.ProductVersion
        $found = $false
        foreach ($n in 'initial_preferences', 'master_preferences') {
            $f = Join-Path $d $n
            if (-not (Test-Path $f)) { continue }
            $found = $true
            $ok = $true; $set = ''
            try { $j = Get-Content -LiteralPath $f -Raw | ConvertFrom-Json; $set = (@($j.PSObject.Properties | ForEach-Object { "$($_.Name)=$((ConvertTo-Json $_.Value -Compress -Depth 4))" }) -join '; ') } catch { $ok = $false; $set = $_.Exception.Message }
            [pscustomobject]@{ Chrome = "$d ($ver)"; File = $f; ValidJson = $ok; Settings = $set }
        }
        if (-not $found) { [pscustomobject]@{ Chrome = "$d ($ver)"; File = '(no initial_preferences or master_preferences)'; ValidJson = $null; Settings = '' } }
    }
}

function Disable-GoogleUpdate {
<#
.SYNOPSIS
Sets the Google Update policies so Chrome is only updated by your deployment (UpdateDefault = 0, AutoUpdateCheckPeriodMinutes = 0) and optionally disables the GoogleUpdate tasks and services.
.PARAMETER DisableTasksAndServices
Also disable the GoogleUpdate scheduled tasks and the gupdate/gupdatem services.
.PARAMETER Undo
Remove the policies (and re-enable tasks/services) instead.
.EXAMPLE
Disable-GoogleUpdate -DisableTasksAndServices
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([switch]$DisableTasksAndServices, [switch]$Undo)
    $key = 'HKLM:\SOFTWARE\Policies\Google\Update'
    $vals = [ordered]@{ UpdateDefault = 0; AutoUpdateCheckPeriodMinutes = 0; 'Update{8A69D345-D564-463C-AFF1-A69D9E530F96}' = 0 }
    if ($PSCmdlet.ShouldProcess($env:COMPUTERNAME, $(if ($Undo) { "Remove $key" } else { "Set $key update policies to 0" }))) {
        if ($Undo) { Remove-Item -Path $key -Recurse -Force -ErrorAction SilentlyContinue }
        else { New-Item -Path $key -Force | Out-Null; foreach ($k in $vals.Keys) { New-ItemProperty -Path $key -Name $k -PropertyType DWord -Value $vals[$k] -Force | Out-Null } }
    }
    if ($DisableTasksAndServices) {
        foreach ($t in @(Get-ScheduledTask -TaskName 'GoogleUpdate*' -ErrorAction SilentlyContinue)) {
            if ($PSCmdlet.ShouldProcess($t.TaskName, $(if ($Undo) { 'Enable task' } else { 'Disable task' }))) { if ($Undo) { $t | Enable-ScheduledTask | Out-Null } else { $t | Disable-ScheduledTask | Out-Null } }
        }
        foreach ($s in @(Get-Service -Name gupdate, gupdatem, GoogleUpdater* -ErrorAction SilentlyContinue)) {
            if ($PSCmdlet.ShouldProcess($s.Name, $(if ($Undo) { 'Startup Manual' } else { 'Stop, startup Disabled' }))) { if ($Undo) { Set-Service -Name $s.Name -StartupType Manual } else { Stop-Service -Name $s.Name -Force -ErrorAction SilentlyContinue; Set-Service -Name $s.Name -StartupType Disabled } }
        }
    }
    $now = Get-ItemProperty -Path $key -ErrorAction SilentlyContinue
    [pscustomobject]@{ Computer = $env:COMPUTERNAME; UpdateDefault = $(if ($now) { $now.UpdateDefault } else { '(not set)' }); CheckPeriod = $(if ($now) { $now.AutoUpdateCheckPeriodMinutes } else { '(not set)' }); Tasks = (@(Get-ScheduledTask -TaskName 'GoogleUpdate*' -ErrorAction SilentlyContinue) | ForEach-Object { "$($_.TaskName)=$($_.State)" }) -join ', ' }
}

function Find-FirefoxInstall {
<#
.SYNOPSIS
Every Firefox on this computer: machine-wide, per-user, Store app, running copies, and optionally a full disk search.
.PARAMETER Deep
Also search all of C: for firefox.exe (slow - finds portable copies).
.EXAMPLE
Find-FirefoxInstall
.NOTES
Run elevated, or other users' profiles are skipped silently. Use "Run on these computers"
to scan many PCs.
#>
    [CmdletBinding()]
    param([switch]$Deep)
    $seen = @{}
    $emit = {
        param($type, $path, $version, $source)
        $key = "$type|$path"
        if ($seen.ContainsKey($key)) { return }
        $seen[$key] = $true
        [pscustomobject]@{ Computer = $env:COMPUTERNAME; Type = $type; Path = [string]$path; Version = [string]$version; Source = $source }
    }
    $files = @("$env:ProgramFiles\Mozilla Firefox\firefox.exe", "${env:ProgramFiles(x86)}\Mozilla Firefox\firefox.exe")
    $files += @(Get-ChildItem 'C:\Users\*\AppData\Local\Mozilla Firefox\firefox.exe' -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName })
    foreach ($f in ($files | Where-Object { $_ -and (Test-Path $_) })) {
        & $emit $(if ($f -like 'C:\Users\*') { 'Per-user' } else { 'Machine-wide' }) $f (Get-Item $f).VersionInfo.ProductVersion 'File'
    }
    Get-ItemProperty 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*', 'Registry::HKEY_USERS\*\Software\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue |
        Where-Object { $_.DisplayName -like '*Firefox*' } |
        ForEach-Object { & $emit $(if ($_.PSPath -like '*HKEY_USERS*') { 'Per-user (registry)' } else { 'Machine-wide (registry)' }) $_.InstallLocation $_.DisplayVersion "Registry: $($_.DisplayName)" }
    Get-AppxPackage -AllUsers *Firefox* -ErrorAction SilentlyContinue | ForEach-Object { & $emit 'Store app' $_.InstallLocation $_.Version "Appx: $($_.Name)" }
    Get-Process firefox -ErrorAction SilentlyContinue | Select-Object -Unique Path | ForEach-Object { if ($_.Path) { & $emit 'Running' $_.Path '' 'Process' } }
    if ($Deep) {
        Get-ChildItem C:\ -Filter firefox.exe -Recurse -ErrorAction SilentlyContinue |
            ForEach-Object { & $emit 'Found on disk' $_.FullName $_.VersionInfo.ProductVersion 'Disk search' }
    }
    if ($seen.Count -eq 0) { [pscustomobject]@{ Computer = $env:COMPUTERNAME; Type = 'Not found'; Path = ''; Version = ''; Source = '' } }
}

function Install-InnoSetupPackage {
<#
.SYNOPSIS
Runs an Inno Setup installer with /VERYSILENT /SUPPRESSMSGBOXES /NORESTART /SP- and a /LOG file, then explains the exit code.
.PARAMETER Path
The setup .exe.
.PARAMETER AllUsers
Add /ALLUSERS (machine-wide install, when the package supports it).
.PARAMETER Directory
Install folder (/DIR=).
.PARAMETER ExtraArguments
Anything else, e.g. /TASKS="desktopicon".
.PARAMETER LogPath
Log file.
.EXAMPLE
Install-InnoSetupPackage -Path .\visionclientlauncher-setup.exe -AllUsers
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)] [string]$Path, [switch]$AllUsers, [string]$Directory, [string]$ExtraArguments, [string]$LogPath)
    if (-not (Test-Path -LiteralPath $Path)) { throw "Not found: $Path" }
    if (-not $LogPath) { $LogPath = Join-Path $env:TEMP (([IO.Path]::GetFileNameWithoutExtension($Path)) + '_install.log') }
    $a = @('/VERYSILENT', '/SUPPRESSMSGBOXES', '/NORESTART', '/SP-', "/LOG=`"$LogPath`"")
    if ($AllUsers) { $a += '/ALLUSERS' }
    if ($Directory) { $a += "/DIR=`"$Directory`"" }
    if ($ExtraArguments) { $a += $ExtraArguments }
    if (-not $PSCmdlet.ShouldProcess($env:COMPUTERNAME, "$Path $($a -join ' ')")) { return }
    $p = Start-Process -FilePath $Path -ArgumentList ($a -join ' ') -Wait -PassThru
    $codes = @{ 0 = 'Success'; 1 = 'Setup failed to initialize'; 2 = 'Cancelled before install'; 3 = 'Fatal error before install'; 4 = 'Fatal error during install'; 5 = 'Cancelled / aborted during install'; 6 = 'Terminated'; 7 = 'PrepareToInstall failed'; 8 = 'PrepareToInstall failed, restart needed' }
    $tail = ''
    if ($p.ExitCode -ne 0 -and (Test-Path $LogPath)) { $tail = (Get-Content -LiteralPath $LogPath -Tail 15) -join "`n" }
    [pscustomobject]@{ Computer = $env:COMPUTERNAME; Package = (Split-Path $Path -Leaf); ExitCode = $p.ExitCode; Meaning = $(if ($codes.ContainsKey($p.ExitCode)) { $codes[$p.ExitCode] } else { 'Unknown' }); Log = $LogPath; LogTail = $tail }
}

function Install-MsiPackage {
<#
.SYNOPSIS
Runs msiexec /i <file> /qn /norestart with a verbose log, waits, and translates the exit code. On failure it shows the lines around "Return value 3" from the log.
.PARAMETER Path
The .msi file.
.PARAMETER Properties
Extra MSI properties, e.g. ALLUSERS=1 INSTALLDIR="D:\App".
.PARAMETER LogPath
Log file. Default: %TEMP%\<msi name>_install.log
.EXAMPLE
Install-MsiPackage -Path \\server\share\GoogleChromeStandaloneEnterprise64.msi
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)] [string]$Path, [string]$Properties, [string]$LogPath)
    if (-not (Test-Path -LiteralPath $Path)) { throw "Not found: $Path" }
    if (-not $LogPath) { $LogPath = Join-Path $env:TEMP (([IO.Path]::GetFileNameWithoutExtension($Path)) + '_install.log') }
    $msiArgs = "/i `"$Path`" /qn /norestart /l*v `"$LogPath`""
    if ($Properties) { $msiArgs += " $Properties" }
    if (-not $PSCmdlet.ShouldProcess($env:COMPUTERNAME, "msiexec $msiArgs")) { return }
    $p = Start-Process -FilePath msiexec.exe -ArgumentList $msiArgs -Wait -PassThru
    $codes = @{ 0 = 'Success'; 1602 = 'Cancelled'; 1603 = 'Fatal error'; 1618 = 'Another install in progress'; 1619 = 'Cannot open package'; 1638 = 'Another version already installed'; 1641 = 'Success - restart started'; 3010 = 'Success - restart required' }
    $detail = ''
    if ($p.ExitCode -notin 0, 1641, 3010 -and (Test-Path $LogPath)) {
        $h = Select-String -LiteralPath $LogPath -Pattern 'Return value 3' -Context 15, 0 -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($h) { $detail = (@($h.Context.PreContext | Where-Object { $_ -match 'error|fail|denied|CustomAction' }) -join "`n") }
    }
    [pscustomobject]@{ Computer = $env:COMPUTERNAME; Package = (Split-Path $Path -Leaf); ExitCode = $p.ExitCode; Meaning = $(if ($codes.ContainsKey($p.ExitCode)) { $codes[$p.ExitCode] } else { 'See Get-ErrorCodeInfo' }); Log = $LogPath; FailureLines = $detail }
}

function Find-PerUserBrowser {
<#
.SYNOPSIS
Looks in every user profile for Chrome or Firefox installed under AppData (outside your managed machine-wide install).
.PARAMETER Browser
Which browsers.
.EXAMPLE
Find-PerUserBrowser
#>
    [CmdletBinding()]
    param([ValidateSet('Chrome', 'Firefox', 'Edge')] [string[]]$Browser = @('Chrome', 'Firefox'))
    $rel = @{ Chrome = 'AppData\Local\Google\Chrome\Application\chrome.exe'; Firefox = 'AppData\Local\Mozilla Firefox\firefox.exe'; Edge = 'AppData\Local\Microsoft\Edge\Application\msedge.exe' }
    foreach ($p in @(Get-ChildItem 'C:\Users' -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -notin 'Public', 'Default', 'Default User', 'All Users' })) {
        foreach ($b in $Browser) {
            $f = Join-Path $p.FullName $rel[$b]
            if (Test-Path -LiteralPath $f) {
                $i = Get-Item -LiteralPath $f
                [pscustomobject]@{ Computer = $env:COMPUTERNAME; User = $p.Name; Browser = $b; Version = $i.VersionInfo.ProductVersion; Modified = $i.LastWriteTime; Path = $f }
            }
        }
    }
}

function Install-RsatTool {
<#
.SYNOPSIS
Installs the AD, Group Policy and/or DNS admin tools - Install-WindowsFeature on servers, Add-WindowsCapability on Windows 10/11.
.PARAMETER Tool
Which tools.
.EXAMPLE
Install-RsatTool -Tool ActiveDirectory, GroupPolicy
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([ValidateSet('ActiveDirectory', 'GroupPolicy', 'DNS')] [string[]]$Tool = @('ActiveDirectory', 'GroupPolicy'))
    $isServer = (Get-CimInstance Win32_OperatingSystem).ProductType -ne 1
    $feat = @{ ActiveDirectory = 'RSAT-AD-PowerShell', 'RSAT-ADDS-Tools'; GroupPolicy = 'GPMC'; DNS = 'RSAT-DNS-Server' }
    $cap = @{ ActiveDirectory = 'Rsat.ActiveDirectory.DS-LDS.Tools~~~~0.0.1.0'; GroupPolicy = 'Rsat.GroupPolicy.Management.Tools~~~~0.0.1.0'; DNS = 'Rsat.Dns.Tools~~~~0.0.1.0' }
    foreach ($t in $Tool) {
        if ($isServer) {
            foreach ($f in @($feat[$t])) {
                if ($PSCmdlet.ShouldProcess($env:COMPUTERNAME, "Install-WindowsFeature $f")) { $r = Install-WindowsFeature -Name $f; [pscustomobject]@{ Tool = $t; Item = $f; Success = $r.Success; Restart = [string]$r.RestartNeeded } }
            }
        }
        elseif ($PSCmdlet.ShouldProcess($env:COMPUTERNAME, "Add-WindowsCapability $($cap[$t])")) {
            $r = Add-WindowsCapability -Online -Name $cap[$t]
            [pscustomobject]@{ Tool = $t; Item = $cap[$t]; Success = $true; Restart = [string]$r.RestartNeeded }
        }
    }
}

function Find-UninstallLeftover {
<#
.SYNOPSIS
Looks for what an uninstall left behind: Program Files / ProgramData folders, Uninstall registry entries, services, InstallShield caches and Start Menu shortcuts that match a name.
.PARAMETER Name
Product or vendor text, e.g. AMS or "Emerson|DeltaV" (regular expression).
.EXAMPLE
Find-UninstallLeftover -Name 'AMS|Emerson'
.NOTES
Nothing is deleted. Remove what is listed by hand (or rename it to .old first) before reinstalling.
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string]$Name)
    $roots = @($env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:ProgramData, "$env:SystemDrive\") | Where-Object { $_ } | Select-Object -Unique
    foreach ($r in $roots) { Get-ChildItem -LiteralPath $r -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match $Name } | ForEach-Object { [pscustomobject]@{ Kind = 'Folder'; Name = $_.Name; Where = $_.FullName } } }
    foreach ($k in 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*') {
        Get-ItemProperty $k -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -match $Name -or $_.Publisher -match $Name } | ForEach-Object { [pscustomobject]@{ Kind = 'Uninstall entry'; Name = "$($_.DisplayName) $($_.DisplayVersion)"; Where = $_.PSPath -replace '^.*::' } }
    }
    foreach ($k in 'HKLM:\SOFTWARE', 'HKLM:\SOFTWARE\WOW6432Node') { Get-ChildItem $k -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match $Name } | ForEach-Object { [pscustomobject]@{ Kind = 'Registry key'; Name = $_.PSChildName; Where = $_.Name } } }
    Get-CimInstance Win32_Service -ErrorAction SilentlyContinue | Where-Object { $_.Name -match $Name -or $_.DisplayName -match $Name -or $_.PathName -match $Name } | ForEach-Object { [pscustomobject]@{ Kind = 'Service'; Name = "$($_.Name) ($($_.State))"; Where = $_.PathName } }
    foreach ($is in "${env:ProgramFiles(x86)}\InstallShield Installation Information", "$env:ProgramFiles\InstallShield Installation Information") {
        if (Test-Path $is) { Get-ChildItem $is -Directory -ErrorAction SilentlyContinue | ForEach-Object { $setup = Get-ChildItem $_.FullName -Filter *.ini -ErrorAction SilentlyContinue | Select-String -Pattern $Name -List -ErrorAction SilentlyContinue; if ($setup) { [pscustomobject]@{ Kind = 'InstallShield cache'; Name = $_.Name; Where = $_.FullName } } } }
    }
    foreach ($sm in "$env:ProgramData\Microsoft\Windows\Start Menu\Programs", "$env:PUBLIC\Desktop") { Get-ChildItem $sm -Recurse -Filter *.lnk -ErrorAction SilentlyContinue | Where-Object { $_.FullName -match $Name } | ForEach-Object { [pscustomobject]@{ Kind = 'Shortcut'; Name = $_.Name; Where = $_.FullName } } }
}

function Get-ErrorCodeInfo {
<#
.SYNOPSIS
Converts an error code between decimal, negative decimal and hex, splits an HRESULT into facility and Win32 code, and looks up the message plus well-known SCCM, Winsock, MSI and Inno Setup codes.
.PARAMETER Code
Codes, e.g. 0x87D00213, 2147942405, -2147024891, 10060, 1603.
.EXAMPLE
Get-ErrorCodeInfo -Code 0x87D00213, 2147942405, 10060
#>
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string[]]$Code)
    $known = @{
        '0x87D00213' = 'SCCM: Timeout occurred (job took longer than the deployment max run time)'; '0x87D00324' = 'SCCM: Application was not detected after install (detection method)'
        '0x87D00607' = 'SCCM: Content not found (DP/boundary)'; '0x87D01106' = 'SCCM: Failed to verify the executable / program not found'; '0x80004005' = 'Unspecified error (E_FAIL)'
        '0x80070005' = 'Access denied'; '0x80070002' = 'File not found'; '0x80070003' = 'Path not found'; '0x8007045D' = 'I/O device error'; '0x800705B4' = 'Timeout'
        '0x80072EE7' = 'Name not resolved (WinHTTP)'; '0x80072EFD' = 'Cannot connect to server (WinHTTP)'; '0x80072F8F' = 'TLS / certificate or clock error (WinHTTP)'
        '0x800F081F' = 'DISM: source files not found'; '0x800F0922' = 'Update failed (reserved partition / .NET / network)'; '0x8024402C' = 'WSUS: proxy or name error'
        '10051' = 'Winsock: network unreachable'; '10054' = 'Winsock: connection reset by peer'; '10060' = 'Winsock: connection timed out (firewall dropping, host down)'; '10061' = 'Winsock: connection refused (nothing listening)'; '10065' = 'Winsock: no route to host'; '11001' = 'Winsock: host not found (DNS)'
        '1602' = 'MSI: user cancelled'; '1603' = 'MSI: fatal error during install (read the /l*v log, search "return value 3")'; '1618' = 'MSI: another install is in progress'; '1619' = 'MSI: package could not be opened'; '1633' = 'MSI: platform not supported'; '1638' = 'MSI: another version is already installed'; '1641' = 'MSI: success, restart started'; '3010' = 'MSI: success, restart required'
    }
    $inno = @{ 1 = 'Inno: setup failed to initialize'; 2 = 'Inno: user cancelled before install'; 3 = 'Inno: fatal error before install'; 4 = 'Inno: fatal error during install'; 5 = 'Inno: user cancelled during install / setup aborted'; 6 = 'Inno: setup terminated by debugger'; 7 = 'Inno: PrepareToInstall failed'; 8 = 'Inno: PrepareToInstall failed, restart needed' }
    foreach ($c in $Code) {
        $t = $c.Trim()
        [long]$n = 0
        if ($t -match '^(0x)?([0-9a-fA-F]{5,8})$' -and ($Matches[1] -or $t -match '[a-fA-F]')) { $n = [Convert]::ToInt64($Matches[2], 16) }
        elseif ($t -match '^-?\d+$') { $n = [long]$t; if ($n -lt 0) { $n = $n + 4294967296 } }
        else { Write-Error "Not a number: $c"; continue }
        $u = [uint32]$n
        $signed = [BitConverter]::ToInt32([BitConverter]::GetBytes($u), 0)
        $msg = ''
        try { $msg = (New-Object System.ComponentModel.Win32Exception($signed)).Message } catch { }
        $facility = ($u -shr 16) -band 0x1FFF
        $w32 = $u -band 0xFFFF
        if ($facility -eq 7) { try { $msg = (New-Object System.ComponentModel.Win32Exception([int]$w32)).Message } catch { } }
        $k = @()
        $hexKey = '0x{0:X8}' -f $u
        if ($known.ContainsKey($hexKey)) { $k += $known[$hexKey] }
        if ($known.ContainsKey([string]$u)) { $k += $known[[string]$u] }
        if ($u -lt 10 -and $inno.ContainsKey([int]$u)) { $k += $inno[[int]$u] }
        if ($msg -match '^Unknown error') { $msg = '' }
        [pscustomobject]@{ Input = $c; Hex = ('0x{0:X8}' -f $u); Decimal = $u; Signed = $signed; Facility = $(if ($u -ge 0x80000000) { $facility } else { $null }); Win32Code = $(if ($facility -eq 7) { $w32 } else { $null }); Known = ($k -join ' | '); Message = $msg }
    }
}

function Reset-MmcCache {
<#
.SYNOPSIS
Moves the user's saved MMC console settings (%AppData%\Microsoft\MMC) aside so consoles start clean.
.EXAMPLE
Reset-MmcCache
.NOTES
The old folder is renamed to MMC.bak-<date>, not deleted. Close all MMC windows first.
#>
    [CmdletBinding(SupportsShouldProcess)]
    param()
    $dir = Join-Path $env:APPDATA 'Microsoft\MMC'
    if (-not (Test-Path $dir)) { [pscustomobject]@{ Folder = $dir; Result = 'Nothing to reset' }; return }
    $bak = "$dir.bak-$(Get-Date -Format yyyyMMdd-HHmmss)"
    if ($PSCmdlet.ShouldProcess($dir, "Rename to $bak")) {
        Rename-Item -LiteralPath $dir -NewName (Split-Path $bak -Leaf) -ErrorAction Stop
        [pscustomobject]@{ Folder = $dir; Result = "Moved to $bak" }
    }
}

function Get-MmcSnapIn {
<#
.SYNOPSIS
Which MMC snap-in a GUID belongs to (from an MMC error), or every registered snap-in matching a name.
.PARAMETER Id
GUID from the error message (braces optional).
.PARAMETER Name
Or text in the snap-in name.
.EXAMPLE
Get-MmcSnapIn -Id 'b05566ad-fe9c-4363-be05-7a4cbb7cb510'
#>
    [CmdletBinding()]
    param([string]$Id, [string]$Name)
    $g = ([string]$Id).Trim().Trim('{', '}')
    Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\MMC\SnapIns' -ErrorAction SilentlyContinue | ForEach-Object {
        $p = Get-ItemProperty -Path $_.PSPath -ErrorAction SilentlyContinue
        $key = $_.PSChildName -replace '^FX:', ''
        $nm = [string]$p.NameString
        if (($g -and $key.Trim('{', '}') -ieq $g) -or ($Name -and $nm -like "*$Name*") -or (-not $g -and -not $Name)) {
            [pscustomobject]@{ Id = $_.PSChildName; Name = $nm; About = [string]$p.About; Type = [string]$p.Type; Assembly = [string]$p.AssemblyName; Version = [string]$p.Version }
        }
    }
}

function Set-NetlogonDebug {
