}

function Get-SqlErrorLog {
<#
.SYNOPSIS
Finds SQL Server ERRORLOG files for every instance and shows the last lines, or only lines that match a pattern.
.PARAMETER Lines
How many lines from the end.
.PARAMETER Pattern
Only lines matching this (e.g. "Login failed|error").
.PARAMETER Instance
Instance name filter (MSSQLSERVER = default instance).
.EXAMPLE
Get-SqlErrorLog -Pattern 'Login failed|error' -Lines 500
#>
    [CmdletBinding()]
    param([int]$Lines = 50, [string]$Pattern, [string]$Instance = '*')
    $roots = @(Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Microsoft SQL Server\Instance Names\SQL' -ErrorAction SilentlyContinue)
    $found = @()
    foreach ($r in $roots) {
        foreach ($p in $r.PSObject.Properties | Where-Object { $_.Name -notlike 'PS*' -and $_.Name -like $Instance }) {
            $params = Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Microsoft SQL Server\$($p.Value)\MSSQLServer\Parameters" -ErrorAction SilentlyContinue
            $e = @($params.PSObject.Properties | Where-Object { $_.Value -is [string] -and $_.Value -like '-e*' }) | Select-Object -First 1
            if ($e) { $found += [pscustomobject]@{ Instance = $p.Name; Log = $e.Value.Substring(2) } }
        }
    }
    if (-not $found.Count) { $found = @(Get-ChildItem "$env:ProgramFiles\Microsoft SQL Server\*\MSSQL\Log\ERRORLOG" -ErrorAction SilentlyContinue | ForEach-Object { [pscustomobject]@{ Instance = ($_.FullName -split '\\')[-4]; Log = $_.FullName } }) }
    foreach ($f in $found) {
        if (-not (Test-Path -LiteralPath $f.Log)) { continue }
        $text = Get-Content -LiteralPath $f.Log -Tail $Lines -ErrorAction SilentlyContinue
        if ($Pattern) { $text = $text | Where-Object { $_ -match $Pattern } }
        foreach ($l in $text) { [pscustomobject]@{ Instance = $f.Instance; Line = $l } }
    }
}

function Get-LocalGroupMembers {
<#
.SYNOPSIS
Members of a local group (default Administrators), with their source and orphaned SIDs flagged.
.PARAMETER Group
Local group name.
.EXAMPLE
Get-LocalGroupMembers -Group Administrators
.NOTES
If Get-LocalGroupMember fails on an orphaned SID (a known Windows bug), this falls back to "net localgroup".
#>
    [CmdletBinding()]
    param([string]$Group = 'Administrators')
    try {
        Get-LocalGroupMember -Group $Group -ErrorAction Stop | ForEach-Object {
            [pscustomobject]@{ Computer = $env:COMPUTERNAME; Group = $Group; Member = $_.Name; Type = [string]$_.ObjectClass; Source = [string]$_.PrincipalSource; SID = [string]$_.SID; Orphaned = ([string]$_.Name -match '^S-1-') }
        }
    }
    catch {
        Write-Warning "Get-LocalGroupMember failed ($($_.Exception.Message)) - using net localgroup."
        $lines = @(net localgroup $Group 2>&1)
        $in = $false
        foreach ($l in $lines) {
            if ([string]$l -match '^-{5,}') { $in = $true; continue }
            if (-not $in -or [string]$l -match 'command completed' -or -not ([string]$l).Trim()) { continue }
            [pscustomobject]@{ Computer = $env:COMPUTERNAME; Group = $Group; Member = ([string]$l).Trim(); Type = ''; Source = ''; SID = ''; Orphaned = ([string]$l -match '^S-1-') }
        }
    }
}

function Get-LocalUserDetail {
<#
.SYNOPSIS
A local account's state: enabled, password last set / expires, last logon, SID and the local groups it is in.
.PARAMETER Name
Local user name. Empty = every local user.
.EXAMPLE
Get-LocalUserDetail -Name AmsServiceUser
.NOTES
A password changed shortly before a service started failing, or a disabled account, are the usual suspects
for "Access is denied" when a service or DCOM server runs as a local account.
#>
    [CmdletBinding()]
    param([string]$Name)
    $users = if ($Name) { @(Get-LocalUser -Name $Name -ErrorAction Stop) } else { @(Get-LocalUser) }
    $groups = @(Get-LocalGroup)
    $memberOf = @{}
    foreach ($g in $groups) {
        foreach ($m in @(Get-LocalGroupMember -Group $g.Name -ErrorAction SilentlyContinue)) {
            $sid = [string]$m.SID
            if (-not $memberOf.ContainsKey($sid)) { $memberOf[$sid] = @() }
            $memberOf[$sid] += $g.Name
        }
    }
    foreach ($u in $users) {
        [pscustomobject]@{
            Name            = $u.Name
            Enabled         = $u.Enabled
            PasswordLastSet = $u.PasswordLastSet
            PasswordExpires = $u.PasswordExpires
            AccountExpires  = $u.AccountExpires
            LastLogon       = $u.LastLogon
            Description     = $u.Description
            SID             = [string]$u.SID
            Groups          = (@($memberOf[[string]$u.SID]) -join ', ')
        }
    }
}

function Get-LoggedOnUser {
<#
.SYNOPSIS
Users logged on to this computer (console and RDP), with session state and idle time - parsed from quser.
.EXAMPLE
Get-LoggedOnUser
#>
    [CmdletBinding()]
    param()
    $lines = @(quser 2>$null)
    if ($lines.Count -le 1) { [pscustomobject]@{ Computer = $env:COMPUTERNAME; User = '(nobody)'; Session = ''; Id = $null; State = ''; Idle = ''; LogonTime = '' }; return }
    foreach ($l in ($lines | Select-Object -Skip 1)) {
        $t = ([string]$l).TrimStart('>').Trim()
        $parts = $t -split '\s{2,}'
        if ($parts.Count -eq 6) { $user, $sess, $id, $state, $idle, $logon = $parts }
        elseif ($parts.Count -eq 5) { $user, $id, $state, $idle, $logon = $parts; $sess = '' }
        else { continue }
        [pscustomobject]@{ Computer = $env:COMPUTERNAME; User = $user; Session = $sess; Id = $id; State = $state; Idle = $idle; LogonTime = $logon }
    }
}

