function New-RandomPassword {
<#
.SYNOPSIS
Cryptographically random passwords that always contain upper case, lower case, digits and symbols, without look-alike characters (O 0 l 1 I).
.PARAMETER Length
Characters per password.
.PARAMETER Count
How many passwords.
.PARAMETER NoSymbols
Letters and digits only (for systems that reject symbols).
.EXAMPLE
New-RandomPassword -Length 20 -Count 5
#>
    [CmdletBinding()]
    param([ValidateRange(8, 128)] [int]$Length = 16, [ValidateRange(1, 100)] [int]$Count = 1, [switch]$NoSymbols)
    $sets = @('ABCDEFGHJKLMNPQRSTUVWXYZ', 'abcdefghijkmnopqrstuvwxyz', '23456789')
    if (-not $NoSymbols) { $sets += '!@#$%^&*-_=+?' }
    $all = -join $sets
    $rng = [Security.Cryptography.RandomNumberGenerator]::Create()
    $pick = {
        param([string]$s)
        $b = New-Object byte[] 4
        $rng.GetBytes($b)
        $s[[int]([BitConverter]::ToUInt32($b, 0) % [uint32]$s.Length)]
    }
    for ($n = 0; $n -lt $Count; $n++) {
        $chars = New-Object System.Collections.Generic.List[char]
        foreach ($s in $sets) { $chars.Add((& $pick $s)) }
        while ($chars.Count -lt $Length) { $chars.Add((& $pick $all)) }
        for ($i = $chars.Count - 1; $i -gt 0; $i--) {
            $b = New-Object byte[] 4; $rng.GetBytes($b)
            $j = [int]([BitConverter]::ToUInt32($b, 0) % [uint32]($i + 1))
            $tmp = $chars[$i]; $chars[$i] = $chars[$j]; $chars[$j] = $tmp
        }
        [pscustomobject]@{ Password = (-join $chars); Length = $Length }
    }
    $rng.Dispose()
}

function Test-PendingReboot {
<#
.SYNOPSIS
Whether Windows is waiting for a reboot, and why (Windows Update, servicing, file rename, computer rename, ConfigMgr).
.EXAMPLE
Test-PendingReboot
#>
    [CmdletBinding()]
    param()
    $reasons = @()
    if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') { $reasons += 'Component servicing (CBS)' }
    if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') { $reasons += 'Windows Update' }
    $pfro = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -Name PendingFileRenameOperations -ErrorAction SilentlyContinue).PendingFileRenameOperations
    if ($pfro) { $reasons += "Pending file renames ($(@($pfro | Where-Object { $_ }).Count))" }
    $active = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ActiveComputerName' -ErrorAction SilentlyContinue).ComputerName
    $pending = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ComputerName' -ErrorAction SilentlyContinue).ComputerName
    if ($active -and $pending -and $active -ne $pending) { $reasons += "Computer rename ($active -> $pending)" }
    try {
        $cm = Invoke-CimMethod -Namespace root\ccm\ClientSDK -ClassName CCM_ClientUtilities -MethodName DetermineIfRebootPending -ErrorAction Stop
        if ($cm.RebootPending -or $cm.IsHardRebootPending) { $reasons += 'ConfigMgr client' }
    } catch { }
    $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
    [pscustomobject]@{ Computer = $env:COMPUTERNAME; RebootPending = ($reasons.Count -gt 0); Reasons = ($reasons -join '; '); LastBoot = $(if ($os) { $os.LastBootUpTime } else { $null }) }
}

