function Repair-WindowsComponentStore {
<#
.SYNOPSIS
Checks and repairs the Windows component store (DISM) and system files (SFC), in the right order.
.PARAMETER Mode
Check (CheckHealth + ScanHealth only) or Repair (RestoreHealth then sfc /scannow).
.PARAMETER Source
For offline or air-gapped machines: a repair source, e.g. WIM:D:\sources\install.wim:1 (from matching Windows media).
.EXAMPLE
Repair-WindowsComponentStore -Mode Check
.EXAMPLE
Repair-WindowsComponentStore -Mode Repair -Source 'WIM:D:\sources\install.wim:1'
.NOTES
Takes 10-30 minutes. Details are in C:\Windows\Logs\CBS\CBS.log and C:\Windows\Logs\DISM\dism.log (Search-CbsLog).
#>
    [CmdletBinding(SupportsShouldProcess)]
    param([ValidateSet('Check', 'Repair')] [string]$Mode = 'Check', [string]$Source)
    $steps = @(@{ Name = 'DISM CheckHealth'; Args = '/Online /Cleanup-Image /CheckHealth' }, @{ Name = 'DISM ScanHealth'; Args = '/Online /Cleanup-Image /ScanHealth' })
    if ($Mode -eq 'Repair') {
        $rh = '/Online /Cleanup-Image /RestoreHealth'
        if ($Source) { $rh += " /Source:$Source /LimitAccess" }
        $steps += @{ Name = 'DISM RestoreHealth'; Args = $rh }
        $steps += @{ Name = 'SFC scannow'; Args = '' }
    }
    foreach ($s in $steps) {
        if (-not $PSCmdlet.ShouldProcess($env:COMPUTERNAME, $s.Name)) { continue }
        $sw = [Diagnostics.Stopwatch]::StartNew()
        $out = if ($s.Name -like 'SFC*') { @(sfc.exe /scannow 2>&1) } else { @(cmd.exe /c "dism.exe $($s.Args)" 2>&1) }
        $text = (($out | ForEach-Object { ([string]$_) -replace "`0", '' }) | Where-Object { $_.Trim() })
        [pscustomobject]@{ Step = $s.Name; ExitCode = $LASTEXITCODE; Minutes = [math]::Round($sw.Elapsed.TotalMinutes, 1); Result = (($text | Select-Object -Last 3) -join ' | ') }
    }
}
